def resolve_country(name):
    """Resolve a country name/code to pycountry's canonical record."""
    if not HAVE_PYCOUNTRY or not name or not name.strip():
        return None
    name = name.strip()
    try:
        return pycountry.countries.lookup(name)
    except LookupError:
        pass
    try:
        results = pycountry.countries.search_fuzzy(name)
        if results:
            return results[0]
    except LookupError:
        pass
    return None


def resolve_country_code(name):
    """Convert a country name or alpha-2/alpha-3 code to an ISO alpha-2 code."""
    country = resolve_country(name)
    return country.alpha_2.lower() if country else None


def canonical_country_codes(value):
    """Return (alpha-2, alpha-3) codes, preserving an unknown code as a fallback."""
    country = resolve_country(value)
    if country:
        return country.alpha_2.upper(), country.alpha_3.upper()
    fallback = str(value or "").strip().upper()
    return fallback[:2], fallback[:3]


