def _tint_alpha_pixmap(source_pixmap, color):
    """Return a solid-color pixmap that preserves only the source alpha channel."""
    if source_pixmap is None or source_pixmap.isNull():
        return None
    img = source_pixmap.toImage().convertToFormat(QImage.Format.Format_ARGB32_Premultiplied)
    out = QImage(img.size(), QImage.Format.Format_ARGB32_Premultiplied)
    out.fill(Qt.GlobalColor.transparent)
    p = QPainter(out)
    p.drawImage(0, 0, img)
    p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceIn)
    c = QColor(color)
    c.setAlpha(255)
    p.fillRect(out.rect(), c)
    p.end()
    return QPixmap.fromImage(out)


def _qimage_to_pil_rgba(qimage):
    """Convert QImage -> Pillow RGBA without relying on ImageQt."""
    if not HAVE_PIL or qimage is None or qimage.isNull():
        return None
    qimg = qimage.convertToFormat(QImage.Format.Format_RGBA8888)
    byte_count = qimg.bytesPerLine() * qimg.height()
    raw = qimg.bits().asstring(byte_count)
    return Image.frombuffer(
        "RGBA", (qimg.width(), qimg.height()), raw,
        "raw", "RGBA", qimg.bytesPerLine(), 1
    ).copy()


def _pil_rgba_to_qpixmap(image):
    """Convert a Pillow RGBA image to an owned QPixmap."""
    if not HAVE_PIL or image is None:
        return None
    rgba = image.convert("RGBA")
    raw = rgba.tobytes("raw", "RGBA")
    qimg = QImage(
        raw, rgba.width, rgba.height, rgba.width * 4,
        QImage.Format.Format_RGBA8888
    ).copy()
    return QPixmap.fromImage(qimg)


def _build_single_blur_glow(source_pixmap, color, blur_radius, opacity):
    """Create one truly continuous Gaussian glow from the source alpha mask.

    Pillow's GaussianBlur is used instead of QGraphicsBlurEffect because the
    latter can render blank/partially clipped when invoked immediately inside
    custom QGraphicsItem paint/export paths on some Qt/Windows configurations.
    This implementation is deterministic for both canvas preview and export.
    """
    if source_pixmap is None or source_pixmap.isNull():
        return None, 0

    blur_radius = max(0.75, float(blur_radius))
    opacity = max(0.0, min(1.0, float(opacity)))
    if opacity <= 0.0:
        return None, 0

    if HAVE_PIL:
        pil = _qimage_to_pil_rgba(source_pixmap.toImage())
        if pil is not None:
            alpha = pil.getchannel("A")
            # 3.25 sigma worth of breathing room keeps even strong glows from
            # clipping while remaining efficient enough for cached UI drawing.
            pad = max(6, int(math.ceil(blur_radius * 3.25)))
            padded_alpha = Image.new("L", (pil.width + pad * 2, pil.height + pad * 2), 0)
            padded_alpha.paste(alpha, (pad, pad))
            blurred_alpha = padded_alpha.filter(ImageFilter.GaussianBlur(radius=blur_radius))

            # Boost the blurred mask slightly so low/medium settings are still
            # visibly useful, while preserving a smooth single falloff.
            gain = 1.18
            lut = [max(0, min(255, int(v * opacity * gain))) for v in range(256)]
            blurred_alpha = blurred_alpha.point(lut)

            c = QColor(color)
            result = Image.new(
                "RGBA", blurred_alpha.size,
                (c.red(), c.green(), c.blue(), 0)
            )
            result.putalpha(blurred_alpha)
            pm = _pil_rgba_to_qpixmap(result)
            if pm is not None and not pm.isNull():
                return pm, pad

    # Conservative Qt fallback for systems where Pillow cannot be imported.
    # It remains a single blur pass; no ring/concentric layering is used.
    tinted = _tint_alpha_pixmap(source_pixmap, color)
    if tinted is None or tinted.isNull():
        return None, 0
    pad = max(8, int(math.ceil(blur_radius * 3.0)))
    padded = QPixmap(tinted.width() + pad * 2, tinted.height() + pad * 2)
    padded.fill(Qt.GlobalColor.transparent)
    pp = QPainter(padded)
    pp.drawPixmap(pad, pad, tinted)
    pp.end()

    scene = QGraphicsScene()
    item = QGraphicsPixmapItem(padded)
    effect = QGraphicsBlurEffect()
    effect.setBlurRadius(blur_radius)
    item.setGraphicsEffect(effect)
    scene.addItem(item)

    out = QImage(padded.size(), QImage.Format.Format_ARGB32_Premultiplied)
    out.fill(Qt.GlobalColor.transparent)
    op = QPainter(out)
    op.setOpacity(opacity)
    op.setRenderHint(QPainter.RenderHint.Antialiasing)
    op.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
    # Render a slightly expanded scene source; the transparent padding keeps the
    # effect inside the target image instead of clipping at the item edge.
    scene.setSceneRect(QRectF(0, 0, padded.width(), padded.height()))
    scene.render(op, QRectF(0, 0, out.width(), out.height()), scene.sceneRect())
    op.end()
    item.setGraphicsEffect(None)
    scene.removeItem(item)
    return QPixmap.fromImage(out), pad


def _shape_mask_pixmap(shape, radius=10.0):
    """Rasterize a QRectF/QPainterPath into a tight alpha mask plus its scene bounds."""
    if isinstance(shape, QPainterPath):
        bounds = shape.boundingRect()
    else:
        bounds = QRectF(shape)
    w = max(2, int(math.ceil(bounds.width())))
    h = max(2, int(math.ceil(bounds.height())))
    pm = QPixmap(w, h)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor(255, 255, 255, 255))
    if isinstance(shape, QPainterPath):
        translated = QPainterPath(shape)
        translated.translate(-bounds.left(), -bounds.top())
        p.drawPath(translated)
    else:
        p.drawRoundedRect(QRectF(0, 0, w, h), radius, radius)
    p.end()
    return pm, bounds


def draw_box_glow(painter, shape, item, radius=10.0):
    """Draw one continuous blurred halo around a box/path instead of visible layers."""
    if not getattr(item, "text_glow_enabled", False):
        return
    color = QColor(getattr(item, "text_glow_color", QColor("#00e575")))
    spread = max(2.0, float(getattr(item, "text_glow_radius", 7)))
    mask, bounds = _shape_mask_pixmap(shape, radius)
    key = (
        round(bounds.left(), 2), round(bounds.top(), 2), round(bounds.width(), 2), round(bounds.height(), 2),
        int(color.rgba()), round(spread, 2), round(radius, 2), isinstance(shape, QPainterPath)
    )
    cache_key = getattr(item, "_soft_box_glow_cache_key", None)
    glow = getattr(item, "_soft_box_glow_cache", None)
    pad = getattr(item, "_soft_box_glow_pad", 0)
    if glow is None or glow.isNull() or cache_key != key:
        glow, pad = _build_single_blur_glow(mask, color, blur_radius=spread * 2.25, opacity=0.94)
        item._soft_box_glow_cache = glow
        item._soft_box_glow_cache_key = key
        item._soft_box_glow_pad = pad
    if glow is None or glow.isNull():
        return
    painter.save()
    painter.setOpacity(1.0)
    painter.drawPixmap(int(round(bounds.left() - pad)), int(round(bounds.top() - pad)), glow)
    painter.restore()


def fetch_flag_image(country_code, size="w640"):
    """Fetch high-resolution country flag from flagcdn.com with local persistent caching."""
    ensure_directory_tree()
    code = resolve_country_code(country_code)
    if not code:
        raise ValueError(f"Unknown ISO country code: {country_code}")
    local_path = os.path.join(FLAG_CACHE_DIR, f"{code}_{size}.png")
    if os.path.exists(local_path) and os.path.getsize(local_path) > 0:
        return local_path
    url = f"https://flagcdn.com/{size}/{code}.png"
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    with urllib.request.urlopen(req, timeout=8) as resp:
        data = resp.read()
    with open(local_path, "wb") as f:
        f.write(data)
    return local_path


def create_procedural_stadium_background():
    """
    Generate a high-resolution, photorealistic procedural tennis stadium background
    matching the Davis Cup aesthetic (green tennis court with lines, crowd atmosphere,
    floodlights, and glowing stadium ambience) if no image file is loaded.
    """
    img = QImage(CANVAS_W, CANVAS_H, QImage.Format.Format_ARGB32)
    img.fill(QColor("#0a1f14"))
    p = QPainter(img)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)

    # 1. Atmospheric Sky & Stadium Lights (Upper 62%)
    sky_grad = QLinearGradient(0, 0, 0, CANVAS_H * 0.65)
    sky_grad.setColorAt(0.0, QColor("#1c4230"))
    sky_grad.setColorAt(0.35, QColor("#2a5c43"))
    sky_grad.setColorAt(0.70, QColor("#1a412e"))
    sky_grad.setColorAt(1.0, QColor("#0e2b1d"))
    p.fillRect(0, 0, CANVAS_W, int(CANVAS_H * 0.65), QBrush(sky_grad))

    # Soft ambient cloud glow in sky
    cloud_radial = QRadialGradient(CANVAS_W * 0.5, CANVAS_H * 0.25, CANVAS_W * 0.55)
    cloud_radial.setColorAt(0.0, QColor(255, 255, 255, 55))
    cloud_radial.setColorAt(0.4, QColor(140, 230, 180, 30))
    cloud_radial.setColorAt(1.0, QColor(0, 0, 0, 0))
    p.fillRect(0, 0, CANVAS_W, int(CANVAS_H * 0.65), QBrush(cloud_radial))

    # Stadium seating tier bands
    p.setPen(Qt.PenStyle.NoPen)
    for i, y_tier in enumerate(range(int(CANVAS_H * 0.38), int(CANVAS_H * 0.62), 16)):
        alpha = 30 + (i % 3) * 15
        p.setBrush(QBrush(QColor(10, 30, 20, alpha)))
        p.drawRect(0, y_tier, CANVAS_W, 12)

    # Stadium Floodlight Towers (left & right)
    for lx in (CANVAS_W * 0.22, CANVAS_W * 0.78):
        light_glow = QRadialGradient(lx, CANVAS_H * 0.44, 200)
        light_glow.setColorAt(0.0, QColor(255, 255, 240, 140))
        light_glow.setColorAt(0.4, QColor(200, 255, 220, 60))
        light_glow.setColorAt(1.0, QColor(0, 0, 0, 0))
        p.fillRect(int(lx - 220), int(CANVAS_H * 0.33), 440, 260, QBrush(light_glow))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(QColor(255, 255, 240, 220)))
        for dy in (-12, 0, 12):
            for dx in (-28, -14, 0, 14, 28):
                p.drawEllipse(QPointF(lx + dx, CANVAS_H * 0.44 + dy), 3.5, 3.5)

    # 2. Green Hard Tennis Court (Lower 38%)
    court_poly = QPolygonF([
        QPointF(0, CANVAS_H * 0.62),
        QPointF(CANVAS_W, CANVAS_H * 0.62),
        QPointF(CANVAS_W, CANVAS_H),
        QPointF(0, CANVAS_H)
    ])
    court_grad = QLinearGradient(0, CANVAS_H * 0.62, 0, CANVAS_H)
    court_grad.setColorAt(0.0, QColor("#113e28"))
    court_grad.setColorAt(0.45, QColor("#195839"))
    court_grad.setColorAt(1.0, QColor("#0d3521"))
    p.setBrush(QBrush(court_grad))
    p.drawPolygon(court_poly)

    # Tennis Court White Lines (Perspective Projection)
    line_pen = QPen(QColor(245, 255, 248, 220))
    line_pen.setWidth(6)
    p.setPen(line_pen)

    # Horizontal baseline / service lines
    p.drawLine(0, int(CANVAS_H * 0.88), CANVAS_W, int(CANVAS_H * 0.88))
    p.setPen(QPen(QColor(245, 255, 248, 160), 4))
    p.drawLine(int(CANVAS_W * 0.15), int(CANVAS_H * 0.73), int(CANVAS_W * 0.85), int(CANVAS_H * 0.73))

    # Center T-service line marker
    p.setPen(QPen(QColor(255, 255, 255, 240), 6))
    p.drawLine(int(CENTER_X), int(CANVAS_H * 0.84), int(CENTER_X), int(CANVAS_H * 0.94))

    # Faded Davis Cup Trophy watermark silhouette on Left
    trophy_path = QPainterPath()
    trophy_cx, trophy_cy = CANVAS_W * 0.08, CANVAS_H * 0.38
    trophy_path.addEllipse(QRectF(trophy_cx - 90, trophy_cy - 120, 180, 240))
    p.setPen(QPen(QColor(200, 240, 215, 35), 3))
    p.setBrush(QBrush(QColor(220, 255, 235, 18)))
    p.drawPath(trophy_path)

    # Faded Globe sphere watermark on Right
    globe_cx, globe_cy = CANVAS_W * 0.92, CANVAS_H * 0.38
    globe_path = QPainterPath()
    globe_path.addEllipse(QRectF(globe_cx - 110, globe_cy - 110, 220, 220))
    p.setPen(QPen(QColor(160, 240, 190, 40), 3))
    p.setBrush(QBrush(QColor(180, 255, 210, 16)))
    p.drawPath(globe_path)

    p.end()
    return img


def create_procedural_flag(country_code, w=240, h=160):
    """
    Generate crisp, un-stretched vector flags in strict 3:2 aspect ratio.
    Accurate colors and geometry for India (IN) and South Korea (KR) with clean fallbacks.
    """
    img = QImage(w, h, QImage.Format.Format_ARGB32)
    img.fill(Qt.GlobalColor.transparent)
    p = QPainter(img)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)

    code = (country_code or "").upper().strip()
    if code in ("IND", "IN"):
        # Indian Tricolor: Saffron, White, Green + Ashoka Chakra
        strip_h = h / 3.0
        p.fillRect(QRectF(0, 0, w, strip_h), QColor("#FF9933"))
        p.fillRect(QRectF(0, strip_h, w, strip_h), QColor("#FFFFFF"))
        p.fillRect(QRectF(0, strip_h * 2, w, strip_h), QColor("#138808"))

        # Ashoka Chakra (Navy Blue) with 24 Spokes
        chakra_r = strip_h * 0.44
        cx, cy = w / 2.0, h / 2.0
        p.setPen(QPen(QColor("#000088"), 2.2))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawEllipse(QPointF(cx, cy), chakra_r, chakra_r)
        p.setPen(QPen(QColor("#000088"), 1.2))
        for deg in range(0, 360, 15):
            rad = math.radians(deg)
            p.drawLine(
                QPointF(cx, cy),
                QPointF(cx + chakra_r * math.cos(rad), cy + chakra_r * math.sin(rad))
            )

    elif code in ("KOR", "KR"):
        # South Korean Taegeukgi
        p.fillRect(QRectF(0, 0, w, h), QColor("#FFFFFF"))
        cx, cy = w / 2.0, h / 2.0
        r = min(w, h) * 0.28

        # Taegeuk Circle (Red on top, Blue on bottom)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#CD2E3A"))
        p.drawPie(QRectF(cx - r, cy - r, r * 2, r * 2), 0, 180 * 16)
        p.setBrush(QColor("#0047A0"))
        p.drawPie(QRectF(cx - r, cy - r, r * 2, r * 2), 180 * 16, 180 * 16)
        # S-curve swirls
        p.setBrush(QColor("#CD2E3A"))
        p.drawEllipse(QPointF(cx - r / 2, cy), r / 2, r / 2)
        p.setBrush(QColor("#0047A0"))
        p.drawEllipse(QPointF(cx + r / 2, cy), r / 2, r / 2)

        # 4 Black Trigrams (Geon, Gon, Gam, Ri)
        p.setPen(QPen(QColor("#000000"), 3.2))
        for ox, oy in [(-1, -0.6), (1, -0.6), (-1, 0.6), (1, 0.6)]:
            p.drawLine(int(cx + ox * r * 1.3), int(cy + oy * r * 0.9),
                       int(cx + ox * r * 0.95), int(cy + oy * r * 0.9))
    else:
        # Clean athletic flag card
        p.fillRect(QRectF(0, 0, w, h), QColor("#1e293b"))
        p.setPen(QPen(QColor("#00e575"), 2))
        p.drawRect(QRectF(1, 1, w - 2, h - 2))
        p.setPen(QColor("#f8fafc"))
        font = QFont("Arial", int(h * 0.35), QFont.Weight.Bold)
        p.setFont(font)
        p.drawText(QRectF(0, 0, w, h), Qt.AlignmentFlag.AlignCenter, code)

    p.end()
    return img


def create_procedural_player_silhouette(name, is_left=True, w=700, h=880):
    """
    Generate an athletic portrait card for the tennis player if no photo is loaded,
    styled with accurate jersey colors and nameplate.
    """
    img = QImage(w, h, QImage.Format.Format_ARGB32)
    img.fill(Qt.GlobalColor.transparent)
    p = QPainter(img)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)

    cx = w * 0.5
    head_y = h * 0.26
    head_r = w * 0.18
    grad_skin = QRadialGradient(cx, head_y, head_r)
    grad_skin.setColorAt(0.0, QColor("#e0b490" if is_left else "#f5d3b3"))
    grad_skin.setColorAt(1.0, QColor("#9c6b45" if is_left else "#c49272"))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QBrush(grad_skin))
    p.drawEllipse(QPointF(cx, head_y), head_r, head_r * 1.15)

    if not is_left:
        # Blue Wilson tennis cap for Soonwoo Kwon
        p.setBrush(QColor("#1d4ed8"))
        p.drawPie(QRectF(cx - head_r * 1.05, head_y - head_r * 1.25, head_r * 2.1, head_r * 1.8), 0, 180 * 16)
        p.drawRoundedRect(QRectF(cx - head_r * 1.15, head_y - head_r * 0.3, head_r * 2.3, 18), 8, 8)

    # Torso with arms folded
    torso_path = QPainterPath()
    torso_path.moveTo(cx - w * 0.42, h)
    torso_path.lineTo(cx - w * 0.35, h * 0.52)
    torso_path.quadTo(cx - w * 0.20, h * 0.42, cx, h * 0.42)
    torso_path.quadTo(cx + w * 0.20, h * 0.42, cx + w * 0.35, h * 0.52)
    torso_path.lineTo(cx + w * 0.42, h)
    torso_path.closeSubpath()

    jersey_grad = QLinearGradient(0, h * 0.42, 0, h)
    if is_left:
        # India Track Jacket (White with Blue panels)
        jersey_grad.setColorAt(0.0, QColor("#f8fafc"))
        jersey_grad.setColorAt(0.5, QColor("#e2e8f0"))
        jersey_grad.setColorAt(1.0, QColor("#cbd5e1"))
    else:
        # South Korea White Track Jacket
        jersey_grad.setColorAt(0.0, QColor("#ffffff"))
        jersey_grad.setColorAt(0.5, QColor("#f1f5f9"))
        jersey_grad.setColorAt(1.0, QColor("#e2e8f0"))

    p.setBrush(QBrush(jersey_grad))
    p.drawPath(torso_path)

    if is_left:
        p.setBrush(QColor("#2563eb"))
        p.drawRect(QRectF(cx - w * 0.32, h * 0.52, w * 0.12, h * 0.35))
        p.drawRect(QRectF(cx + w * 0.20, h * 0.52, w * 0.12, h * 0.35))
        # Small Indian flag crest
        p.fillRect(QRectF(cx + w * 0.08, h * 0.62, 38, 24), QColor("#FF9933"))
        p.fillRect(QRectF(cx + w * 0.08, h * 0.62 + 8, 38, 8), QColor("#FFFFFF"))
        p.fillRect(QRectF(cx + w * 0.08, h * 0.62 + 16, 38, 8), QColor("#138808"))
    else:
        p.fillRect(QRectF(cx - w * 0.18, h * 0.62, 36, 24), QColor("#FFFFFF"))
        p.setPen(QPen(QColor("#000000"), 1))
        p.drawRect(QRectF(cx - w * 0.18, h * 0.62, 36, 24))

    p.setPen(QColor("#ffffff"))
    font = QFont("Arial", 28, QFont.Weight.Black)
    p.setFont(font)
    p.drawText(QRectF(0, h * 0.80, w, 50), Qt.AlignmentFlag.AlignCenter, name.upper())

    p.end()
    return img


# ==============================================================================
# CANVA-STYLE 8-POINT RESIZE HANDLES
# ==============================================================================

HANDLE_EDGES = ["nw", "n", "ne", "e", "se", "s", "sw", "w"]
HANDLE_CURSORS = {
    "nw": Qt.CursorShape.SizeFDiagCursor, "se": Qt.CursorShape.SizeFDiagCursor,
    "ne": Qt.CursorShape.SizeBDiagCursor, "sw": Qt.CursorShape.SizeBDiagCursor,
    "n": Qt.CursorShape.SizeVerCursor, "s": Qt.CursorShape.SizeVerCursor,
    "e": Qt.CursorShape.SizeHorCursor, "w": Qt.CursorShape.SizeHorCursor,
}


class CanvasResizeHandle(QGraphicsRectItem):
    """
    Canva-style interactive handle placed around selected elements.
    Supports corner & edge dragging with real-time resizing and cursor changes.
    """
    SIZE = 16

    def __init__(self, target_item, edge, app):
        super().__init__(-self.SIZE / 2, -self.SIZE / 2, self.SIZE, self.SIZE)
        self.target_item = target_item
        self.edge = edge
        self.app = app
        self.setBrush(QBrush(QColor("#00e575")))  # Neon green accent
        self.setPen(QPen(QColor("#ffffff"), 2))
        self.setZValue(5000)
        self.setCursor(QCursor(HANDLE_CURSORS.get(edge, Qt.CursorShape.ArrowCursor)))
        self.setAcceptHoverEvents(True)
        self._dragging = False

    def mousePressEvent(self, event):
        self._dragging = True
        self.app.push_undo_snapshot()
        event.accept()

    def mouseMoveEvent(self, event):
        if self._dragging:
            self.app.resize_item_from_handle(self.target_item, self.edge, event.scenePos())
        event.accept()

    def mouseReleaseEvent(self, event):
        self._dragging = False
        self.app.clear_guides()
        self.app.commit_history_state()
        event.accept()


# ==============================================================================
# BASE DRAGGABLE GRAPHICS ITEM
# ==============================================================================

class DraggableStudioItem(QGraphicsItem):
    """
    Abstract base class providing Canva-style drag, select, snapping,
    aspect ratio handling, shadow rendering, and geometry synchronization.
    """
    def __init__(self, center_x, center_y, width, height, app=None, role="generic"):
        super().__init__()
        self.setFlags(
            QGraphicsItem.GraphicsItemFlag.ItemIsMovable
            | QGraphicsItem.GraphicsItemFlag.ItemIsSelectable
            | QGraphicsItem.GraphicsItemFlag.ItemSendsGeometryChanges
            | QGraphicsItem.GraphicsItemFlag.ItemIsFocusable
        )
        self._center = QPointF(center_x, center_y)
        self._w = max(20.0, float(width))
        self._h = max(20.0, float(height))
        self.app = app
        self.role = role
        self._aspect_locked = False
        self._aspect_ratio = self._w / max(1.0, self._h)
        self._shadow = copy.deepcopy(DEFAULT_SHADOW)
        self._suppress_move = False
        self.on_move = None
        self._recenter()

    def boundingRect(self):
        return QRectF(-self._w / 2, -self._h / 2, self._w, self._h)

    def center(self):
        return (self._center.x(), self._center.y())

    def set_center(self, x, y):
        self._center = QPointF(x, y)
        self._recenter()

    def size(self):
        return (self._w, self._h)

    def half_size(self):
        return (self._w / 2.0, self._h / 2.0)

    def set_size_px(self, w, h, keep_aspect=None):
        if keep_aspect is None:
            keep_aspect = self._aspect_locked
        w = max(20.0, float(w))
        h = max(20.0, float(h))
        if keep_aspect and self._aspect_ratio:
            h = max(20.0, w / self._aspect_ratio)
        self.prepareGeometryChange()
        self._w = w
        self._h = h
        self._recenter()
        self.update()

    def set_aspect_locked(self, locked):
        self._aspect_locked = bool(locked)
        if self._h > 0:
            self._aspect_ratio = self._w / self._h

    def aspect_locked(self):
        return self._aspect_locked

    def aspect_ratio(self):
        return self._aspect_ratio

    def set_aspect_ratio(self, ratio):
        self._aspect_ratio = ratio if ratio and ratio > 0 else (self._w / max(1.0, self._h))
        if ratio:
            self.set_size_px(self._w, self._w / ratio, keep_aspect=False)

    def _recenter(self):
        self._suppress_move = True
        self.setPos(self._center.x(), self._center.y())
        self._suppress_move = False
        if self.app:
            self.app.reposition_handles()

    def shadow_settings(self):
        return copy.deepcopy(self._shadow)

    def set_shadow_settings(self, settings):
        self._shadow = {**DEFAULT_SHADOW, **(settings or {})}
        self._apply_shadow()

    def _apply_shadow(self):
        if not self._shadow.get("enabled"):
            self.setGraphicsEffect(None)
            return
        effect = QGraphicsDropShadowEffect()
        mode = self._shadow.get("color_mode", "Black / Dark")
        if mode == "Custom":
            color = QColor(self._shadow.get("custom_color", "#000000"))
        else:
            color = QColor("#000000")

        # Design-tool style shadow tuning. Qt's raw drop-shadow can look much
        # harder in exported PNGs than it does in the editor, especially at
        # 1920x1080/4K. Keep the user's controls intact but map them to a softer
        # visual response: slightly lower effective opacity/distance and a wider
        # blur falloff. This keeps preview and export visually consistent.
        opacity = (self._shadow.get("opacity", 60) / 100.0) * 0.72
        color.setAlpha(max(0, min(255, int(255 * opacity))))
        effect.setColor(color)
        dist = float(self._shadow.get("distance", 22)) * 0.78
        dx, dy = SHADOW_DIRECTIONS.get(self._shadow.get("direction"), (0.707, 0.707))
        effect.setOffset(dx * dist, dy * dist)
        blur_val = float(self._shadow.get("blur", 35)) * 1.28 + float(self._shadow.get("spread", 15)) * 0.55
        effect.setBlurRadius(max(0.0, blur_val))
        self.setGraphicsEffect(effect)

    def mousePressEvent(self, event):
        if self.app:
            self.app.push_undo_snapshot()
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        super().mouseReleaseEvent(event)
        if self.app:
            self.app.clear_guides()
            self.app.commit_history_state()

    def itemChange(self, change, value):
        if (
            change == QGraphicsItem.GraphicsItemChange.ItemPositionChange
            and self.app and not self._suppress_move
            and hasattr(self.app, "snap_enabled_checkbox")
        ):
            hw, hh = self.half_size()
            proposed_center = value
            snapped = self.app.snap_center(self, proposed_center, hw, hh)
            return snapped

        if (
            change == QGraphicsItem.GraphicsItemChange.ItemPositionHasChanged
            and not self._suppress_move
        ):
            self._center = self.pos()
            if self.on_move:
                self.on_move(self)
            if self.app:
                self.app.reposition_handles()

        return super().itemChange(change, value)


# ==============================================================================
# PLAYER CUTOUT GRAPHICS ITEM (WITH UNDERLINE)
# ==============================================================================

class PlayerCutoutItem(DraggableStudioItem):
    """
    Movable cutout portrait of a tennis player.
    Supports:
      - Custom image loading with high-DPI scaling and transparency.
      - Independent reference-style glow behind the player cutout.
      - Luminous neon green horizontal underline directly below picture.
      - Horizontal/vertical flipping (mirroring), rotation, opacity, and Canva handles.
    """
    def __init__(self, center_x, center_y, width, height, player_name, is_left=True, app=None):
        super().__init__(center_x, center_y, width, height, app=app, role="player")
        self.player_name = player_name
        self.is_left = is_left
        self._source_path = None
        self._pixmap = None
        self._flip_h = False
        self._flip_v = False
        self._aspect_locked = True
        self.setZValue(25)

        # Reference-style glow behind player image. These are deliberately separate
        # from the generic shadow system so users can keep a zero-offset colored halo
        # while still using normal shadows on other graphic elements.
        self.glow_enabled = True
        self.glow_color = QColor("#00e575")
        self.glow_intensity = 68       # 0..100 -> visual radius / density
        self.glow_opacity = 62         # 0..100 -> alpha strength
        self._glow_tint_cache = None
        self._glow_tint_cache_key = None
        self._glow_blur_cache = None
        self._glow_blur_cache_key = None
        self._glow_blur_pad = 0

        # Horizontal accent below the player cutout.
        self.underline_enabled = True
        self.underline_color = QColor("#00ff88")
        self.underline_thickness = 5.0
        self.underline_width = 460.0
        self.underline_offset_y = 6.0

        self._init_default_graphic()

    def _init_default_graphic(self):
        self._source_path = None
        self._pixmap = None
        self._invalidate_glow_cache()
        self.update()

    def _invalidate_glow_cache(self):
        self._glow_tint_cache = None
        self._glow_tint_cache_key = None
        self._glow_blur_cache = None
        self._glow_blur_cache_key = None
        self._glow_blur_pad = 0

    def clear_image(self):
        """Remove loaded photo and revert to clean blank placeholder."""
        self.prepareGeometryChange()
        self._source_path = None
        self._pixmap = None
        self._invalidate_glow_cache()
        self.update()
        if self.app:
            self.app.reposition_handles()

    def mouseDoubleClickEvent(self, event):
        if self.app:
            self.app._load_player_photo(self)
        event.accept()

    def load_image(self, path):
        pix = QPixmap(path)
        if pix.isNull():
            return False
        self.prepareGeometryChange()
        self._source_path = path
        self._pixmap = pix
        self._invalidate_glow_cache()
        self._aspect_ratio = pix.width() / max(1.0, pix.height())
        if self._aspect_locked:
            self._h = self._w / self._aspect_ratio
        self.update()
        if self.app:
            self.app.reposition_handles()
        return True

    def source_path(self):
        return self._source_path

    def set_flip_h(self, flip):
        self._flip_h = bool(flip)
        self.update()

    def flip_h(self):
        return self._flip_h

    def set_flip_v(self, flip):
        self._flip_v = bool(flip)
        self.update()

    def flip_v(self):
        return self._flip_v

    def set_glow_enabled(self, enabled):
        self.prepareGeometryChange()
        self.glow_enabled = bool(enabled)
        self.update()

    def set_glow_color(self, color):
        c = QColor(color)
        if c.isValid():
            self.glow_color = c
            self._invalidate_glow_cache()
            self.update()

    def set_glow_intensity(self, value):
        self.prepareGeometryChange()
        self.glow_intensity = max(0, min(100, int(value)))
        self.update()

    def set_glow_opacity(self, value):
        self.prepareGeometryChange()
        self.glow_opacity = max(0, min(100, int(value)))
        self.update()

    def _glow_radius_px(self):
        # 8..52 scene pixels, enough to produce the poster-style green aura without
        # turning the player into a soft blob at 1080p or 4K export.
        return 8.0 + (self.glow_intensity / 100.0) * 44.0

    def _tinted_glow_pixmap(self):
        """Return a cached solid-color silhouette using the source image alpha."""
        if not self._pixmap or self._pixmap.isNull():
            return None
        key = (int(self._pixmap.cacheKey()), self.glow_color.rgba())
        if self._glow_tint_cache is not None and self._glow_tint_cache_key == key:
            return self._glow_tint_cache

        img = QImage(self._pixmap.size(), QImage.Format.Format_ARGB32_Premultiplied)
        img.fill(Qt.GlobalColor.transparent)
        p = QPainter(img)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        p.drawPixmap(0, 0, self._pixmap)
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceIn)
        solid = QColor(self.glow_color)
        solid.setAlpha(255)
        p.fillRect(img.rect(), solid)
        p.end()
        self._glow_tint_cache = QPixmap.fromImage(img)
        self._glow_tint_cache_key = key
        return self._glow_tint_cache

    def boundingRect(self):
        hw = self._w / 2.0
        hh = self._h / 2.0
        pad_x = 10.0
        pad_y_top = 10.0
        pad_y_bot = 10.0

        if self.glow_enabled and self.glow_opacity > 0 and self._pixmap:
            glow_pad = self._glow_radius_px() * 2.1 + 14.0
            pad_x = max(pad_x, glow_pad)
            pad_y_top = max(pad_y_top, glow_pad)
            pad_y_bot = max(pad_y_bot, glow_pad)

        if self.underline_enabled and self.underline_thickness > 0:
            half_uw = min(hw * 1.5, self.underline_width / 2.0)
            pad_x = max(pad_x, half_uw - hw + 20.0)
            pad_y_bot = max(pad_y_bot, self.underline_offset_y + self.underline_thickness * 4.0 + 20.0)
        return QRectF(-hw - pad_x, -hh - pad_y_top,
                      self._w + 2.0 * pad_x, self._h + pad_y_top + pad_y_bot)

    def _paint_player_glow(self, painter, draw_rect):
        """Paint a single continuous blurred silhouette behind the player."""
        if not self.glow_enabled or self.glow_opacity <= 0 or self.glow_intensity <= 0:
            return
        if not self._pixmap or self._pixmap.isNull():
            return
        target_w = max(2, int(round(draw_rect.width())))
        target_h = max(2, int(round(draw_rect.height())))
        key = (
            int(self._pixmap.cacheKey()), target_w, target_h, int(self.glow_color.rgba()),
            int(self.glow_intensity), int(self.glow_opacity)
        )
        if self._glow_blur_cache is None or self._glow_blur_cache.isNull() or self._glow_blur_cache_key != key:
            scaled = self._pixmap.scaled(target_w, target_h, Qt.AspectRatioMode.IgnoreAspectRatio,
                                          Qt.TransformationMode.SmoothTransformation)
            blur = 5.0 + (self.glow_intensity / 100.0) * 22.0
            opacity = (self.glow_opacity / 100.0) * 0.96
            glow, pad = _build_single_blur_glow(scaled, self.glow_color, blur, opacity)
            self._glow_blur_cache = glow
            self._glow_blur_cache_key = key
            self._glow_blur_pad = pad
        glow = self._glow_blur_cache
        if glow is None or glow.isNull():
            return
        painter.save()
        sx = -1.0 if self._flip_h else 1.0
        sy = -1.0 if self._flip_v else 1.0
        if sx < 0 or sy < 0:
            painter.scale(sx, sy)
        pad = self._glow_blur_pad
        painter.setOpacity(1.0)
        painter.drawPixmap(int(round(draw_rect.left() - pad)), int(round(draw_rect.top() - pad)), glow)
        painter.restore()

    def paint(self, painter, option, widget=None):
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)

        hw, hh = self._w / 2.0, self._h / 2.0
        draw_rect = QRectF(-hw, -hh, self._w, self._h)

        # Glow must be drawn first so the original player remains crisp.
        if self._pixmap and not self._pixmap.isNull():
            self._paint_player_glow(painter, draw_rect)

        if self._pixmap and not self._pixmap.isNull():
            painter.save()
            sx = -1.0 if self._flip_h else 1.0
            sy = -1.0 if self._flip_v else 1.0
            if sx < 0 or sy < 0:
                painter.scale(sx, sy)
            painter.drawPixmap(draw_rect.toRect(), self._pixmap)
            painter.restore()
        else:
            fallback_rect = draw_rect
            painter.save()
            painter.setBrush(QBrush(QColor(8, 24, 18, 205)))
            dash_pen = QPen(QColor("#00e575"), 2.2, Qt.PenStyle.DashLine)
            dash_pen.setDashPattern([6, 5])
            painter.setPen(dash_pen)
            painter.drawRoundedRect(fallback_rect, 20, 20)

            side_label = "PLAYER 1" if self.is_left else "PLAYER 2"
            f_icon = QFont("Segoe UI", 46)
            painter.setFont(f_icon)
            painter.setPen(QColor("#00e575"))
            painter.drawText(QRectF(-hw, -hh + 180, self._w, 75), Qt.AlignmentFlag.AlignCenter, "👤")

            f_name = QFont("Arial", 24, QFont.Weight.Bold)
            painter.setFont(f_name)
            painter.setPen(QColor("#ffffff"))
            painter.drawText(QRectF(-hw + 20, -hh + 265, self._w - 40, 45),
                             Qt.AlignmentFlag.AlignCenter, f"+ Upload {side_label} Photo")

            f_sub = QFont("Arial", 14)
            painter.setFont(f_sub)
            painter.setPen(QColor("#94a3b8"))
            painter.drawText(QRectF(-hw + 20, -hh + 315, self._w - 40, 60),
                             Qt.AlignmentFlag.AlignCenter,
                             "Double-click here or use sidebar\nto load player cutout (PNG)")
            painter.restore()

        if self.underline_enabled and self.underline_thickness > 0:
            line_y = hh + self.underline_offset_y
            half_uw = min(hw * 1.2, self.underline_width / 2.0)
            core_pen = QPen(self.underline_color, self.underline_thickness)
            core_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            painter.setPen(core_pen)
            painter.drawLine(QPointF(-half_uw, line_y), QPointF(half_uw, line_y))

            inner_pen = QPen(QColor(255, 255, 255, 220), max(1.5, self.underline_thickness * 0.45))
            inner_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            painter.setPen(inner_pen)
            painter.drawLine(QPointF(-half_uw * 0.8, line_y), QPointF(half_uw * 0.8, line_y))

        painter.restore()


# ==============================================================================
# SLANTED PLAYER NAMEPLATE ITEM (WITH SLANT & ROTATION ANGLES)
# ==============================================================================

class SlantedNameplateItem(DraggableStudioItem):
    """
    Athletic player-name banner matching the supplied reference:
      - First name / leading names use a clean medium-weight sans style.
      - Last name is heavier and italic for emphasis.
      - Thin luminous accent line sits just below the badge.
      - Badge and text slant remain independently adjustable.
    """
    def __init__(self, center_x, center_y, width, height, text, app=None):
        super().__init__(center_x, center_y, width, height, app=app, role="nameplate")
        init_text_glow(self)
        self.text = text
        self.font_family = "Arial"
        self.font_size = 44
        self.font_bold = True
        self.font_italic = False
        self.font_underline = False
        self.letter_spacing = 2
        self.slant_deg = 15.0
        self.text_slant_deg = 0.0
        self.bg_color1 = QColor("#021f12")
        self.bg_color2 = QColor("#064024")
        self.border_color = QColor("#00e575")
        self.border_width = 2.5
        self.text_color = QColor("#ffffff")

        # Reference name typography.
        self.reference_split_style = True
        self.first_name_weight = int(QFont.Weight.Medium)
        self.last_name_weight = int(QFont.Weight.Black)
        self.last_name_italic = True
        self.force_uppercase = True

        # Small line directly beneath player name, as in the reference graphic.
        self.accent_line_enabled = True
        self.accent_line_color = QColor("#34f59a")
        self.accent_line_thickness = 2.5
        self.accent_line_width_ratio = 0.94
        self.accent_line_offset_y = 4.0
        self.setZValue(40)

    def set_name(self, name):
        self.text = str(name).strip()
        self.update()

    def set_reference_split_style(self, enabled):
        self.reference_split_style = bool(enabled)
        self.update()

    def mouseDoubleClickEvent(self, event):
        if self.app:
            new_text, ok = QInputDialog.getText(self.app, "Edit Player Name", "Player Name:", text=self.text)
            if ok and new_text.strip():
                self.app.push_undo_snapshot()
                self.set_name(new_text)
                if self is self.app.nameplate_left and hasattr(self.app, "input_name_l"):
                    self.app.input_name_l.setText(self.text)
                elif self is self.app.nameplate_right and hasattr(self.app, "input_name_r"):
                    self.app.input_name_r.setText(self.text)
        event.accept()

    def boundingRect(self):
        slant_offset = abs(math.tan(math.radians(self.slant_deg))) * (self._h / 2.0)
        pad_x = slant_offset + self.border_width + 12.0
        pad_top = self.border_width + 8.0
        line_extra = 0.0
        if self.accent_line_enabled:
            line_extra = self.accent_line_offset_y + self.accent_line_thickness * 3.0 + 8.0
        pad_bottom = max(self.border_width + 8.0, line_extra)
        hw, hh = self._w / 2.0, self._h / 2.0
        return QRectF(-hw - pad_x, -hh - pad_top,
                      self._w + 2.0 * pad_x, self._h + pad_top + pad_bottom)

    def _display_parts(self):
        parts = [p for p in self.text.strip().split() if p]
        if self.force_uppercase:
            parts = [p.upper() for p in parts]
        if len(parts) < 2:
            return ("", parts[0] if parts else "")
        return (" ".join(parts[:-1]), parts[-1])

    def _paint_reference_name(self, painter, text_rect):
        first, last = self._display_parts()
        if not last:
            return
        if not first or not self.reference_split_style:
            f = QFont(self.font_family, self.font_size)
            f.setBold(self.font_bold)
            f.setItalic(self.font_italic)
            f.setUnderline(self.font_underline)
            f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, self.letter_spacing)
            painter.setFont(f)
            draw_text_with_glow(painter, text_rect, Qt.AlignmentFlag.AlignCenter,
                                (first + " " + last).strip(), self.text_color, self)
            return

        first_font = QFont(self.font_family, self.font_size)
        first_font.setWeight(QFont.Weight(self.first_name_weight))
        first_font.setItalic(False)
        first_font.setUnderline(self.font_underline)
        first_font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, max(0, self.letter_spacing - 1))

        last_font = QFont(self.font_family, self.font_size)
        last_font.setWeight(QFont.Weight(self.last_name_weight))
        last_font.setItalic(self.last_name_italic)
        last_font.setUnderline(self.font_underline)
        last_font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, self.letter_spacing)

        fm_first = QFontMetricsF(first_font)
        fm_last = QFontMetricsF(last_font)
        first_w = fm_first.horizontalAdvance(first)
        last_w = fm_last.horizontalAdvance(last)
        gap = max(10.0, self.font_size * 0.22)
        total_w = first_w + gap + last_w
        start_x = text_rect.center().x() - total_w / 2.0

        # Shared baseline using the larger ascent/descent makes both styles read as
        # one continuous name even when their font weights/italic metrics differ.
        ascent = max(fm_first.ascent(), fm_last.ascent())
        descent = max(fm_first.descent(), fm_last.descent())
        baseline_y = text_rect.center().y() + (ascent - descent) / 2.0

        painter.setPen(self.text_color)
        painter.setFont(first_font)
        painter.drawText(QPointF(start_x, baseline_y), first)
        painter.setFont(last_font)
        painter.drawText(QPointF(start_x + first_w + gap, baseline_y), last)

    def paint(self, painter, option, widget=None):
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.TextAntialiasing)

        w, h = self._w, self._h
        hw, hh = w / 2.0, h / 2.0
        slant_offset = math.tan(math.radians(self.slant_deg)) * (h / 2.0)

        path = QPainterPath()
        path.moveTo(-hw + slant_offset, -hh)
        path.lineTo(hw + slant_offset, -hh)
        path.lineTo(hw - slant_offset, hh)
        path.lineTo(-hw - slant_offset, hh)
        path.closeSubpath()
        draw_box_glow(painter, path, self)

        grad = QLinearGradient(-hw, -hh, hw, hh)
        grad.setColorAt(0.0, self.bg_color1)
        grad.setColorAt(1.0, self.bg_color2)
        painter.setBrush(QBrush(grad))
        painter.setPen(QPen(self.border_color, self.border_width) if self.border_width > 0 else Qt.PenStyle.NoPen)
        painter.drawPath(path)

        painter.save()
        if self.text_slant_deg != 0.0:
            painter.rotate(self.text_slant_deg)
        text_rect = QRectF(-hw + 22, -hh, w - 44, h)
        self._paint_reference_name(painter, text_rect)
        painter.restore()

        if self.accent_line_enabled and self.accent_line_thickness > 0:
            line_y = hh + self.accent_line_offset_y
            half_line = hw * max(0.10, min(1.30, self.accent_line_width_ratio))
            soft = QColor(self.accent_line_color)
            soft.setAlpha(85)
            soft_pen = QPen(soft, self.accent_line_thickness * 2.2)
            soft_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            painter.setPen(soft_pen)
            painter.drawLine(QPointF(-half_line, line_y), QPointF(half_line, line_y))
            core_pen = QPen(self.accent_line_color, self.accent_line_thickness)
            core_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            painter.setPen(core_pen)
            painter.drawLine(QPointF(-half_line, line_y), QPointF(half_line, line_y))

        painter.restore()


# ==============================================================================
# SLANTED MATCH BANNER ITEM ("DAY 1" / "MATCH 1")
# ==============================================================================

class SlantedMatchBannerItem(DraggableStudioItem):
    """
    Angled trapezoidal match badge (e.g. 'DAY 1' in emerald or 'MATCH 1' in silver-white).
    3D perspective bevel, gradient fill, drop shadow, and typography controls.
    """
    def __init__(self, center_x, center_y, width, height, text,
                 is_dark_green=True, app=None, role="match_banner"):
        super().__init__(center_x, center_y, width, height, app=app, role=role)
        init_text_glow(self)
        self.text = text
        self.is_dark_green = is_dark_green
        self.font_family = "Arial"
        self.font_size = 54 if is_dark_green else 58
        self.font_bold = True
        self.font_italic = True
        self.font_underline = False
        self.letter_spacing = 2
        self.slant_deg = 15.0

        if is_dark_green:
            self.bg_color1 = QColor("#042b17")
            self.bg_color2 = QColor("#0d5430")
            self.border_color = QColor("#00ff88")
            self.text_color = QColor("#ffffff")
        else:
            self.bg_color1 = QColor("#ffffff")
            self.bg_color2 = QColor("#dbe4ee")
            self.border_color = QColor("#cbd5e1")
            self.text_color = QColor("#000000")

        self.border_width = 2.0
        self.setZValue(35)
        self._shadow["enabled"] = True
        self._apply_shadow()

    def set_banner_text(self, text):
        self.text = str(text).strip()
        self.update()

    def mouseDoubleClickEvent(self, event):
        if self.app:
            new_text, ok = QInputDialog.getText(self.app, "Edit Banner Text", "Banner Text:", text=self.text)
            if ok and new_text.strip():
                self.app.push_undo_snapshot()
                self.set_banner_text(new_text)
                if self.role == "banner_day" and hasattr(self.app, "input_day_text"):
                    self.app.input_day_text.setText(self.text)
                elif self.role == "banner_match" and hasattr(self.app, "input_match_text"):
                    self.app.input_match_text.setText(self.text)
        event.accept()

    def boundingRect(self):
        slant_offset = abs(math.tan(math.radians(self.slant_deg))) * (self._h / 2.0)
        pad_x = slant_offset + self.border_width + 12.0
        pad_y = self.border_width + 8.0
        hw, hh = self._w / 2.0, self._h / 2.0
        return QRectF(-hw - pad_x, -hh - pad_y, self._w + 2.0 * pad_x, self._h + 2.0 * pad_y)

    def paint(self, painter, option, widget=None):
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        w, h = self._w, self._h
        hw, hh = w / 2.0, h / 2.0
        slant_offset = math.tan(math.radians(self.slant_deg)) * (h / 2.0)

        path = QPainterPath()
        path.moveTo(-hw + slant_offset, -hh)
        path.lineTo(hw + slant_offset, -hh)
        path.lineTo(hw - slant_offset, hh)
        path.lineTo(-hw - slant_offset, hh)
        path.closeSubpath()
        draw_box_glow(painter, path, self)

        grad = QLinearGradient(-hw, -hh, -hw, hh)
        grad.setColorAt(0.0, self.bg_color1)
        grad.setColorAt(1.0, self.bg_color2)
        painter.setBrush(QBrush(grad))

        if self.border_width > 0:
            painter.setPen(QPen(self.border_color, self.border_width))
        else:
            painter.setPen(Qt.PenStyle.NoPen)
        painter.drawPath(path)

        f = QFont(self.font_family, self.font_size)
        f.setBold(self.font_bold)
        f.setItalic(self.font_italic)
        f.setUnderline(self.font_underline)
        f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, self.letter_spacing)
        painter.setFont(f)
        text_rect = QRectF(-hw + 20, -hh, w - 40, h)
        draw_text_with_glow(painter, text_rect, Qt.AlignmentFlag.AlignCenter,
                            self.text, self.text_color, self)

        painter.restore()


# ==============================================================================
# COUNTRY PILL ITEM (FLAG + CODE WITH ASPECT RATIO PRESERVATION)
# ==============================================================================

class CountryPillItem(DraggableStudioItem):
    """
    Reference-style country matchup card: a separate rounded flag card plus a
    dark emerald country-code card. Flags always preserve their native aspect ratio.
    """
    def __init__(self, center_x, center_y, width, height, country_code,
                 flag_on_left=True, app=None):
        super().__init__(center_x, center_y, width, height, app=app, role="country_pill")
        init_text_glow(self)
        self.country_code = country_code
        self.flag_on_left = flag_on_left
        self.font_family = "Arial"
        self.font_size = 38
        self.font_bold = True
        self.font_italic = True
        self.font_underline = False
        self.letter_spacing = 1
        # Existing fields are retained for preset backwards compatibility. bg_color
        # is the main code-card color in the new reference UI.
        self.bg_color = QColor("#07351f")
        self.border_color = QColor("#2f9f68")
        self.border_width = 1.5
        self.text_color = QColor("#ffffff")
        # Legacy preset fields are retained for backwards compatibility only.
        # v4.5 keeps the flag edge-to-edge by default, but now optionally allows
        # an editor-controlled border on demand from the Match section.
        self.flag_card_color = QColor(0, 0, 0, 0)
        self.flag_border_enabled = False
        self.flag_border_color = QColor("#ffffff")
        self.flag_border_width = 5.0
        self.flag_glow_enabled = False
        self.flag_glow_color = QColor("#00e575")
        self.flag_glow_intensity = 58
        self.flag_glow_opacity = 48
        # Flag-only shadow. This deliberately does NOT affect the country-code
        # card, so the Match panel shadow control behaves exactly like a flag
        # shadow instead of shadowing the whole matchup element.
        self.flag_shadow = copy.deepcopy(DEFAULT_SHADOW)
        self.flag_shadow["enabled"] = False
        self.flag_shadow["custom_color"] = "#000000"
        self.flag_shadow["color_mode"] = "Custom"
        self.card_gap = 7.0
        self.reference_card_style = True
        self._flag_source_path = None
        self._flag_pixmap = None
        self._flag_glow_cache = None
        self._flag_glow_cache_key = None
        self._flag_glow_pad = 0
        self.setZValue(30)
        self._init_flag()

    def _init_flag(self):
        alpha2, alpha3 = canonical_country_codes(self.country_code)
        if alpha3:
            self.country_code = alpha3
        cached = os.path.join(FLAG_CACHE_DIR, f"{alpha2.lower()}_w640.png") if alpha2 else ""
        if cached and os.path.exists(cached) and self.load_flag(cached):
            return
        cached_320 = os.path.join(FLAG_CACHE_DIR, f"{alpha2.lower()}_w320.png") if alpha2 else ""
        if cached_320 and os.path.exists(cached_320) and self.load_flag(cached_320):
            return

        # India/Korea are built procedurally first, making the supplied template
        # fully standalone and instant even when the machine is offline.
        if alpha3 in ("IND", "KOR"):
            flag_img = create_procedural_flag(alpha3, 360, 240)
            self._flag_source_path = None
            self._flag_pixmap = QPixmap.fromImage(flag_img)
            self.update()
            return

        try:
            if alpha2:
                downloaded = fetch_flag_image(alpha2, size="w640")
                if self.load_flag(downloaded):
                    return
        except (OSError, ValueError, urllib.error.URLError):
            pass

        flag_img = create_procedural_flag(alpha3, 360, 240)
        self._flag_source_path = None
        self._flag_pixmap = QPixmap.fromImage(flag_img)
        self.update()

    def load_flag(self, path):
        pix = QPixmap(path)
        if pix.isNull():
            return False
        self._flag_source_path = path
        self._flag_pixmap = pix
        self._flag_glow_cache = None
        self._flag_glow_cache_key = None
        self.update()
        return True

    def set_code(self, code):
        raw = str(code or "").strip()
        if not raw:
            return
        _alpha2, alpha3 = canonical_country_codes(raw)
        if not alpha3:
            return
        self.country_code = alpha3
        self._init_flag()
        self.update()

    def mouseDoubleClickEvent(self, event):
        if self.app:
            new_code, ok = QInputDialog.getText(self.app, "Edit Country Code",
                                                "Code (e.g. IND, KOR, USA, ESP):",
                                                text=self.country_code)
            if ok and new_code.strip():
                self.app.push_undo_snapshot()
                self.set_code(new_code.strip())
                if self is self.app.pill_left and hasattr(self.app, "input_code_l"):
                    self.app.input_code_l.setText(self.country_code)
                elif self is self.app.pill_right and hasattr(self.app, "input_code_r"):
                    self.app.input_code_r.setText(self.country_code)
        event.accept()

    def boundingRect(self):
        pad = max(self.border_width + 6.0, 10.0)
        if self.flag_glow_enabled and self.flag_glow_opacity > 0:
            pad = max(pad, 22.0 + (self.flag_glow_intensity / 100.0) * 48.0)
        if self.flag_shadow.get("enabled"):
            pad = max(
                pad,
                float(self.flag_shadow.get("distance", 22))
                + float(self.flag_shadow.get("blur", 35)) * 0.7
                + float(self.flag_shadow.get("spread", 15)) * 0.35
                + 8.0,
            )
        hw, hh = self._w / 2.0, self._h / 2.0
        return QRectF(-hw - pad, -hh - pad, self._w + 2.0 * pad, self._h + 2.0 * pad)

    @staticmethod
    def _draw_soft_card_shadow(painter, rect, radius):
        for grow, alpha in ((7.0, 22), (4.0, 34), (2.0, 45)):
            c = QColor(0, 0, 0, alpha)
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(c)
            painter.drawRoundedRect(rect.adjusted(-grow, -grow, grow, grow), radius + grow, radius + grow)

    def _paint_flag_shadow(self, painter, rect, radius):
        """Paint a soft flag-only shadow with a smooth falloff (no visible bands)."""
        s = self.flag_shadow
        if not s.get("enabled"):
            return
        direction = s.get("direction", "Bottom-Right")
        dx, dy = SHADOW_DIRECTIONS.get(direction, (0.707, 0.707))
        # A small visual remap makes the exported result closer to modern design
        # tools instead of a hard sticker-like shadow.
        distance = float(s.get("distance", 22)) * 0.82
        blur = max(0.0, float(s.get("blur", 35)))
        spread = max(0.0, float(s.get("spread", 15))) * 0.45
        opacity = max(0.0, min(1.0, float(s.get("opacity", 60)) / 100.0)) * 0.72
        color = QColor(s.get("custom_color", "#000000"))
        shadow_rect = rect.translated(dx * distance, dy * distance)
        max_grow = spread + 5.0 + blur * 0.72
        layers = 24
        painter.save()
        painter.setPen(Qt.PenStyle.NoPen)
        # Draw from outside -> inside using many tiny-alpha fills. Since the flag
        # itself is drawn afterwards, the centre is hidden and only the smooth
        # shadow halo remains visible.
        for i in range(layers, 0, -1):
            t = i / layers
            grow = max_grow * t
            # Very low alpha per layer avoids the concentric neon rings seen in
            # earlier exports while accumulated opacity stays controllable.
            alpha_scale = (0.020 + 0.030 * (1.0 - t))
            c = QColor(color)
            c.setAlpha(max(0, min(255, int(255 * opacity * alpha_scale))))
            painter.setBrush(c)
            rr = shadow_rect.adjusted(-grow, -grow, grow, grow)
            painter.drawRoundedRect(rr, radius + grow * 0.28, radius + grow * 0.28)
        painter.restore()

    def _paint_flag_glow(self, painter, rect, radius):
        """Single blurred rounded-rectangle halo; never draws visible glow layers."""
        if not self.flag_glow_enabled or self.flag_glow_opacity <= 0 or self.flag_glow_intensity <= 0:
            return
        w = max(2, int(round(rect.width())))
        h = max(2, int(round(rect.height())))
        key = (w, h, round(radius, 2), int(self.flag_glow_color.rgba()),
               int(self.flag_glow_intensity), int(self.flag_glow_opacity))
        if self._flag_glow_cache is None or self._flag_glow_cache.isNull() or self._flag_glow_cache_key != key:
            mask = QPixmap(w, h)
            mask.fill(Qt.GlobalColor.transparent)
            mp = QPainter(mask)
            mp.setRenderHint(QPainter.RenderHint.Antialiasing)
            mp.setPen(Qt.PenStyle.NoPen)
            mp.setBrush(QColor(255, 255, 255, 255))
            mp.drawRoundedRect(QRectF(0, 0, w, h), radius, radius)
            mp.end()
            blur = 4.0 + (self.flag_glow_intensity / 100.0) * 18.0
            opacity = (self.flag_glow_opacity / 100.0) * 0.96
            glow, pad = _build_single_blur_glow(mask, self.flag_glow_color, blur, opacity)
            self._flag_glow_cache = glow
            self._flag_glow_cache_key = key
            self._flag_glow_pad = pad
        glow = self._flag_glow_cache
        if glow is None or glow.isNull():
            return
        painter.save()
        painter.setOpacity(1.0)
        painter.drawPixmap(int(round(rect.left() - self._flag_glow_pad)),
                           int(round(rect.top() - self._flag_glow_pad)), glow)
        painter.restore()

    def paint(self, painter, option, widget=None):
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.TextAntialiasing)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)

        full = QRectF(-self._w / 2.0, -self._h / 2.0, self._w, self._h)
        # Reference proportions. The flag itself is rendered directly, with no
        # surrounding card. Use the loaded image aspect ratio so there can be
        # no white breathing-margin that looks like a border.
        card_h = full.height() * 0.96
        if self._flag_pixmap and not self._flag_pixmap.isNull() and self._flag_pixmap.height() > 0:
            flag_aspect = self._flag_pixmap.width() / self._flag_pixmap.height()
            flag_aspect = max(1.10, min(1.85, flag_aspect))
        else:
            flag_aspect = 1.50
        flag_w = card_h * flag_aspect
        code_w = card_h * 1.52
        desired_w = flag_w + self.card_gap + code_w
        if desired_w > self._w:
            scale = max(0.20, (self._w - self.card_gap) / max(1.0, flag_w + code_w))
            card_h *= scale
            flag_w *= scale
            code_w *= scale
        total_w = flag_w + self.card_gap + code_w
        x0 = -total_w / 2.0
        y0 = -card_h / 2.0

        if self.flag_on_left:
            flag_rect = QRectF(x0, y0, flag_w, card_h)
            code_rect = QRectF(x0 + flag_w + self.card_gap, y0, code_w, card_h)
        else:
            code_rect = QRectF(x0, y0, code_w, card_h)
            flag_rect = QRectF(x0 + code_w + self.card_gap, y0, flag_w, card_h)

        flag_radius = card_h * 0.12
        code_radius = card_h * 0.11

        # IMPORTANT: draw the flag itself edge-to-edge. There is deliberately
        # no flag-card background and no padding. Optional glow and border are
        # drawn only when explicitly enabled from the Match section.
        self._paint_flag_shadow(painter, flag_rect, flag_radius)
        self._paint_flag_glow(painter, flag_rect, flag_radius)
        if self._flag_pixmap and not self._flag_pixmap.isNull():
            painter.save()
            clip = QPainterPath()
            clip.addRoundedRect(flag_rect, flag_radius, flag_radius)
            painter.setClipPath(clip)
            scaled = self._flag_pixmap.scaled(
                max(1, int(round(flag_rect.width()))),
                max(1, int(round(flag_rect.height()))),
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation
            )
            dx = flag_rect.left() + (flag_rect.width() - scaled.width()) / 2.0
            dy = flag_rect.top() + (flag_rect.height() - scaled.height()) / 2.0
            painter.drawPixmap(int(round(dx)), int(round(dy)), scaled)
            painter.restore()

        if self.flag_border_enabled and self.flag_border_width > 0:
            painter.save()
            pen = QPen(self.flag_border_color, self.flag_border_width)
            painter.setPen(pen)
            painter.setBrush(Qt.BrushStyle.NoBrush)
            inset = self.flag_border_width / 2.0
            painter.drawRoundedRect(flag_rect.adjusted(inset, inset, -inset, -inset), flag_radius, flag_radius)
            painter.restore()

        # Only the country-code card keeps its own shadow/rim styling.
        self._draw_soft_card_shadow(painter, code_rect, code_radius)

        # Country-code card: dark green gradient, subtle green rim.
        draw_box_glow(painter, code_rect, self, code_radius)
        grad = QLinearGradient(code_rect.left(), code_rect.top(), code_rect.right(), code_rect.bottom())
        grad.setColorAt(0.0, QColor("#0b4329"))
        grad.setColorAt(1.0, self.bg_color)
        painter.setBrush(QBrush(grad))
        painter.setPen(QPen(self.border_color, self.border_width))
        painter.drawRoundedRect(code_rect, code_radius, code_radius)

        f = QFont(self.font_family, self.font_size)
        f.setBold(self.font_bold)
        f.setItalic(self.font_italic)
        f.setUnderline(self.font_underline)
        f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, self.letter_spacing)
        painter.setFont(f)
        draw_text_with_glow(painter, code_rect, Qt.AlignmentFlag.AlignCenter,
                            self.country_code, self.text_color, self)

        painter.restore()


# ==============================================================================
# "VS" DIVIDER ITEM
# ==============================================================================

class VsDividerItem(DraggableStudioItem):
    """
    Center matchup separator: vertical line | 'VS' text | vertical line.
    """
    def __init__(self, center_x, center_y, width, height, app=None):
        super().__init__(center_x, center_y, width, height, app=app, role="vs_divider")
        init_text_glow(self)
        self.text = "VS"
        self.font_family = "Arial"
        self.font_size = 46
        self.font_bold = True
        self.font_italic = False
        self.font_underline = False
        self.letter_spacing = 1
        self.text_color = QColor("#000000")
        self.line_color = QColor(0, 0, 0, 160)
        self.setZValue(30)

    def mouseDoubleClickEvent(self, event):
        if self.app:
            new_text, ok = QInputDialog.getText(self.app, "Edit VS Text", "Text:", text=self.text)
            if ok and new_text.strip():
                self.app.push_undo_snapshot()
                self.text = new_text.strip()
                self.update()
        event.accept()

    def paint(self, painter, option, widget=None):
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        w, h = self._w, self._h
        hw, hh = w / 2.0, h / 2.0
        draw_box_glow(painter, self.boundingRect().adjusted(8, 8, -8, -8), self, 8)

        painter.setPen(QPen(self.line_color, 2.5))
        painter.drawLine(QPointF(-hw + 10, -hh + 8), QPointF(-hw + 10, hh - 8))
        painter.drawLine(QPointF(hw - 10, -hh + 8), QPointF(hw - 10, hh - 8))

        f = QFont(self.font_family, self.font_size)
        f.setBold(self.font_bold)
        f.setItalic(self.font_italic)
        f.setUnderline(self.font_underline)
        f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, self.letter_spacing)
        painter.setFont(f)
        draw_text_with_glow(painter, self.boundingRect(), Qt.AlignmentFlag.AlignCenter,
                            self.text, self.text_color, self)

        painter.restore()


# ==============================================================================
# TOURNAMENT LOGO & HEADER ITEM (UPLOAD, ADD, REPLACE, REMOVE, RESET)
# ==============================================================================

class TournamentLogoItem(DraggableStudioItem):
    """
    Official Tournament Logo & Header item matching the reference graphic.
    Full capabilities:
      - Upload & Add custom logo image (PNG transparency, JPG, WebP, SVG).
      - Replace logo image seamlessly.
      - Remove logo image without breaking layout.
      - Reset to official Davis Cup circular emblem and title.
      - Preserves high-DPI scaling and true aspect ratio.
      - Fully movable and resizable with Canva 8-point handles.
    """
    def __init__(self, center_x, center_y, width, height, app=None):
        super().__init__(center_x, center_y, width, height, app=app, role="tournament_logo")
        init_text_glow(self)
        self.title_text = "DAVIS CUP®"
        self.font_family = "Montserrat"
        self.font_size = 68
        self.font_bold = True
        self.font_italic = False
        self.font_underline = False
        self.letter_spacing = 2
        self.text_color = QColor("#000000")
        self.emblem_color = QColor("#00a352")  # Official Davis Cup green

        # Multi-logo support. Legacy single-logo attributes are kept in sync
        # with the first loaded logo for backward-compatible presets/code.
        self.custom_logo_paths = []
        self.custom_logo_pixmaps = []
        self.custom_logo_path = None
        self.custom_logo_pixmap = None
        self.logo_spacing = 18.0
        self.show_logo = True
        # The supplied default logo artwork already contains the DAVIS CUP wordmark.
        self.show_title = False
        self.default_logo_pixmap = embedded_default_davis_logo()
        self.logo_glow_enabled = False
        self.logo_glow_color = QColor("#00e575")
        self.logo_glow_intensity = 58
        self.logo_glow_opacity = 58
        # Cache tinted alpha silhouettes so the glow follows the actual logo
        # pixels instead of painting a rectangular/rounded card behind it.
        self._logo_glow_cache = {}
        self.setZValue(30)
        self._aspect_locked = False

        self._init_default_logo()

    def _invalidate_logo_glow_cache(self):
        self._logo_glow_cache = {}

    def _logo_glow_padding(self):
        if not self.logo_glow_enabled or self.logo_glow_opacity <= 0 or self.logo_glow_intensity <= 0:
            return 0.0
        # Paint can extend beyond the logical editor box. Returning that extra
        # area in boundingRect prevents trails/clipping while the logo is moved.
        return 14.0 + (self.logo_glow_intensity / 100.0) * 62.0

    def boundingRect(self):
        pad = self._logo_glow_padding()
        hw, hh = self._w / 2.0, self._h / 2.0
        return QRectF(-hw - pad, -hh - pad, self._w + 2.0 * pad, self._h + 2.0 * pad)

    def _init_default_logo(self):
        # Use the exact user-supplied Davis Cup artwork embedded in this script.
        self.custom_logo_paths = []
        self.custom_logo_pixmaps = []
        self._sync_legacy_logo_fields()
        self._invalidate_logo_glow_cache()
        self.show_logo = True
        self.show_title = False
        if self.default_logo_pixmap is None or self.default_logo_pixmap.isNull():
            self.default_logo_pixmap = embedded_default_davis_logo()

    def _sync_legacy_logo_fields(self):
        """Keep v3/v4 single-logo fields compatible with the new multi-logo model."""
        self.custom_logo_path = self.custom_logo_paths[0] if self.custom_logo_paths else None
        self.custom_logo_pixmap = self.custom_logo_pixmaps[0] if self.custom_logo_pixmaps else None

    @staticmethod
    def _load_and_trim_logo(file_path):
        """Load a logo and crop transparent outer padding that causes visual scaling glitches."""
        pix = QPixmap(file_path)
        if pix.isNull():
            return None
        try:
            mask = pix.mask()
            if not mask.isNull():
                bounds = mask.boundingRect()
                if bounds.isValid() and bounds.width() > 1 and bounds.height() > 1:
                    # Only crop when there is a meaningful transparent margin.
                    if bounds.width() < pix.width() or bounds.height() < pix.height():
                        pix = pix.copy(bounds)
        except Exception:
            pass
        return pix

    def set_custom_logos(self, file_paths, replace=True):
        """Load one or many custom logos. Returns the number successfully loaded."""
        valid_paths = []
        valid_pixmaps = []
        seen = set()
        for file_path in file_paths or []:
            norm = os.path.abspath(str(file_path))
            if norm in seen:
                continue
            seen.add(norm)
            pix = self._load_and_trim_logo(norm)
            if pix is None or pix.isNull():
                continue
            valid_paths.append(norm)
            valid_pixmaps.append(pix)
        if not valid_pixmaps:
            return 0
        if replace:
            self.custom_logo_paths = valid_paths
            self.custom_logo_pixmaps = valid_pixmaps
        else:
            existing = {os.path.abspath(p) for p in self.custom_logo_paths}
            for pth, pix in zip(valid_paths, valid_pixmaps):
                if pth not in existing:
                    self.custom_logo_paths.append(pth)
                    self.custom_logo_pixmaps.append(pix)
                    existing.add(pth)
        self._sync_legacy_logo_fields()
        self._invalidate_logo_glow_cache()
        self.show_logo = True
        self.update()
        return len(valid_pixmaps)

    def set_custom_logo(self, file_path):
        """Backward-compatible single-logo replace."""
        return self.set_custom_logos([file_path], replace=True) > 0

    def remove_custom_logo_at(self, index):
        if 0 <= index < len(self.custom_logo_pixmaps):
            del self.custom_logo_pixmaps[index]
            del self.custom_logo_paths[index]
            self._sync_legacy_logo_fields()
            self._invalidate_logo_glow_cache()
            self.update()
            return True
        return False

    def remove_logo(self):
        """Remove all custom logos from the header and hide the logo area."""
        self.custom_logo_paths = []
        self.custom_logo_pixmaps = []
        self._sync_legacy_logo_fields()
        self._invalidate_logo_glow_cache()
        self.show_logo = False
        self.update()

    def clear_custom_logos_keep_visible(self):
        """Clear custom logos and fall back to the official mark without hiding it."""
        self.custom_logo_paths = []
        self.custom_logo_pixmaps = []
        self._sync_legacy_logo_fields()
        self._invalidate_logo_glow_cache()
        self.show_logo = True
        self.update()

    def reset_to_davis_cup(self):
        """Reset to the official procedural Davis Cup circular emblem & title."""
        self.custom_logo_paths = []
        self.custom_logo_pixmaps = []
        self._sync_legacy_logo_fields()
        self._invalidate_logo_glow_cache()
        self.show_logo = True
        self.show_title = False
        self.default_logo_pixmap = embedded_default_davis_logo()
        self.title_text = "DAVIS CUP®"
        self.font_family = "Montserrat"
        self.font_size = 68
        self.font_bold = True
        self.font_italic = False
        self.font_underline = False
        self.letter_spacing = 2
        self.emblem_color = QColor("#00a352")
        self.text_color = QColor("#000000")
        self.update()

    def mouseDoubleClickEvent(self, event):
        if self.app:
            new_text, ok = QInputDialog.getText(self.app, "Edit Tournament Title", "Title:", text=self.title_text)
            if ok and new_text.strip():
                self.app.push_undo_snapshot()
                self.title_text = new_text.strip()
                self.update()
                if hasattr(self.app, "input_header_text"):
                    self.app.input_header_text.setText(self.title_text)
        event.accept()

    def _tinted_logo_glow_pixmap(self, pixmap):
        """Return a glow-color silhouette preserving the source logo alpha."""
        if pixmap is None or pixmap.isNull():
            return None
        key = (int(pixmap.cacheKey()), int(self.logo_glow_color.rgba()))
        cached = self._logo_glow_cache.get(key)
        if cached is not None and not cached.isNull():
            return cached

        img = pixmap.toImage().convertToFormat(QImage.Format.Format_ARGB32)
        tinted = QImage(img.size(), QImage.Format.Format_ARGB32)
        tinted.fill(Qt.GlobalColor.transparent)
        p = QPainter(tinted)
        p.drawImage(0, 0, img)
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceIn)
        c = QColor(self.logo_glow_color)
        c.setAlpha(255)
        p.fillRect(tinted.rect(), c)
        p.end()
        result = QPixmap.fromImage(tinted)
        self._logo_glow_cache[key] = result
        return result

    def _paint_logo_pixmap_glow(self, painter, source_pixmap, draw_rect):
        """One blurred alpha-following logo halo; no offset rings or duplicated edges."""
        if not self.logo_glow_enabled or self.logo_glow_opacity <= 0 or self.logo_glow_intensity <= 0:
            return
        target_w = max(2, int(round(draw_rect.width())))
        target_h = max(2, int(round(draw_rect.height())))
        key = ("blur", int(source_pixmap.cacheKey()), target_w, target_h,
               int(self.logo_glow_color.rgba()), int(self.logo_glow_intensity), int(self.logo_glow_opacity))
        cached = self._logo_glow_cache.get(key)
        if cached is None:
            scaled = source_pixmap.scaled(target_w, target_h, Qt.AspectRatioMode.IgnoreAspectRatio,
                                           Qt.TransformationMode.SmoothTransformation)
            blur = 4.0 + (self.logo_glow_intensity / 100.0) * 20.0
            opacity = (self.logo_glow_opacity / 100.0) * 0.96
            cached = _build_single_blur_glow(scaled, self.logo_glow_color, blur, opacity)
            self._logo_glow_cache[key] = cached
        glow, pad = cached
        if glow is None or glow.isNull():
            return
        painter.save()
        painter.setOpacity(1.0)
        painter.drawPixmap(int(round(draw_rect.left() - pad)), int(round(draw_rect.top() - pad)), glow)
        painter.restore()

    def _paint_procedural_logo_glow(self, painter, rect):
        """Single blurred ellipse halo for the procedural Davis Cup mark."""
        if not self.logo_glow_enabled or self.logo_glow_opacity <= 0 or self.logo_glow_intensity <= 0:
            return
        w = max(2, int(round(rect.width())))
        h = max(2, int(round(rect.height())))
        key = ("proc_blur", w, h, int(self.logo_glow_color.rgba()),
               int(self.logo_glow_intensity), int(self.logo_glow_opacity))
        cached = self._logo_glow_cache.get(key)
        if cached is None:
            mask = QPixmap(w, h)
            mask.fill(Qt.GlobalColor.transparent)
            mp = QPainter(mask)
            mp.setRenderHint(QPainter.RenderHint.Antialiasing)
            mp.setPen(Qt.PenStyle.NoPen)
            mp.setBrush(QColor(255, 255, 255, 255))
            mp.drawEllipse(QRectF(0, 0, w, h))
            mp.end()
            blur = 5.0 + (self.logo_glow_intensity / 100.0) * 21.0
            opacity = (self.logo_glow_opacity / 100.0) * 0.96
            cached = _build_single_blur_glow(mask, self.logo_glow_color, blur, opacity)
            self._logo_glow_cache[key] = cached
        glow, pad = cached
        if glow is None or glow.isNull():
            return
        painter.save()
        painter.setOpacity(1.0)
        painter.drawPixmap(int(round(rect.left() - pad)), int(round(rect.top() - pad)), glow)
        painter.restore()

    def paint(self, painter, option, widget=None):
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)

        w, h = self._w, self._h
        hw, hh = w / 2.0, h / 2.0
        draw_box_glow(painter, QRectF(-hw, -hh, w, h), self, 14)

        has_title = self.show_title and bool(self.title_text.strip())
        if self.show_logo and has_title:
            emblem_h = h * 0.52
            emblem_r = emblem_h / 2.0
            emblem_cx = 0
            emblem_cy = -hh + emblem_r + 2
            text_y = emblem_cy + emblem_r + 6
            text_h = h - (emblem_h + 10)
        elif self.show_logo:
            emblem_h = h * 0.90
            emblem_r = emblem_h / 2.0
            emblem_cx = 0
            emblem_cy = 0
            text_y = 0
            text_h = 0
        else:
            emblem_r = 0
            text_y = -hh
            text_h = h

        # 1. DRAW LOGO(S) (MULTI-CUSTOM PIXMAPS OR OFFICIAL EMBLEM)
        if self.show_logo:
            logos = [pm for pm in self.custom_logo_pixmaps if pm and not pm.isNull()]
            if logos:
                # Fit all selected logos into one stable strip without stretching/cropping.
                avail_w = max(20.0, w * 0.92)
                avail_h = max(20.0, emblem_h * 0.92)
                count = len(logos)
                spacing = self.logo_spacing if count > 1 else 0.0
                natural_widths = []
                for pm in logos:
                    ratio = pm.width() / max(1.0, pm.height())
                    natural_widths.append(avail_h * ratio)
                total_nat = sum(natural_widths) + spacing * max(0, count - 1)
                scale_factor = min(1.0, avail_w / max(1.0, total_nat))
                draw_h = max(8.0, avail_h * scale_factor)
                draw_ws = [draw_h * (pm.width() / max(1.0, pm.height())) for pm in logos]
                total_w = sum(draw_ws) + spacing * max(0, count - 1)
                cursor_x = emblem_cx - total_w / 2.0
                for pm, target_w in zip(logos, draw_ws):
                    scaled_logo = pm.scaled(
                        max(1, int(round(target_w))), max(1, int(round(draw_h))),
                        Qt.AspectRatioMode.KeepAspectRatio,
                        Qt.TransformationMode.SmoothTransformation
                    )
                    lx = cursor_x + (target_w - scaled_logo.width()) / 2.0
                    ly = emblem_cy - scaled_logo.height() / 2.0
                    logo_rect = QRectF(lx, ly, scaled_logo.width(), scaled_logo.height())
                    # Glow follows the actual transparent pixels of each logo,
                    # never a rounded rectangular backplate.
                    self._paint_logo_pixmap_glow(painter, pm, logo_rect)
                    painter.drawPixmap(int(round(lx)), int(round(ly)), scaled_logo)
                    cursor_x += target_w + spacing
            else:
                default_pm = self.default_logo_pixmap
                if default_pm is not None and not default_pm.isNull():
                    # The default supplied artwork includes emblem + DAVIS CUP text,
                    # so fit it as one transparent logo and let glow follow its alpha.
                    avail_w = max(20.0, w * 0.88)
                    avail_h = max(20.0, h * 0.88)
                    scaled_logo = default_pm.scaled(
                        max(1, int(round(avail_w))), max(1, int(round(avail_h))),
                        Qt.AspectRatioMode.KeepAspectRatio,
                        Qt.TransformationMode.SmoothTransformation,
                    )
                    lx = -scaled_logo.width() / 2.0
                    ly = -scaled_logo.height() / 2.0
                    logo_rect = QRectF(lx, ly, scaled_logo.width(), scaled_logo.height())
                    self._paint_logo_pixmap_glow(painter, default_pm, logo_rect)
                    painter.drawPixmap(int(round(lx)), int(round(ly)), scaled_logo)
                else:
                    # Last-resort vector fallback if the embedded image cannot load.
                    self._paint_procedural_logo_glow(
                        painter,
                        QRectF(emblem_cx - emblem_r, emblem_cy - emblem_r, emblem_r * 2.0, emblem_r * 2.0),
                    )
                    painter.setPen(Qt.PenStyle.NoPen)
                    painter.setBrush(QBrush(self.emblem_color))
                    painter.drawEllipse(QPointF(emblem_cx, emblem_cy), emblem_r, emblem_r)
                    swoosh = QPainterPath()
                    swoosh.moveTo(emblem_cx - emblem_r * 0.65, emblem_cy + emblem_r * 0.1)
                    swoosh.cubicTo(
                        emblem_cx - emblem_r * 0.2, emblem_cy - emblem_r * 0.55,
                        emblem_cx + emblem_r * 0.4, emblem_cy - emblem_r * 0.35,
                        emblem_cx + emblem_r * 0.7, emblem_cy - emblem_r * 0.05
                    )
                    swoosh.cubicTo(
                        emblem_cx + emblem_r * 0.2, emblem_cy + emblem_r * 0.25,
                        emblem_cx - emblem_r * 0.3, emblem_cy + emblem_r * 0.35,
                        emblem_cx - emblem_r * 0.65, emblem_cy + emblem_r * 0.1
                    )
                    swoosh.closeSubpath()
                    painter.setBrush(QColor("#ffffff"))
                    painter.drawPath(swoosh)

        # 2. DRAW TOURNAMENT TITLE TYPOGRAPHY
        if has_title:
            f = QFont(self.font_family, self.font_size)
            f.setBold(self.font_bold)
            f.setItalic(self.font_italic)
            f.setUnderline(self.font_underline)
            f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, self.letter_spacing)
            text_rect = QRectF(-hw, text_y, w, text_h)
            suffix_start = len(self.title_text.rstrip(SUPERSCRIPT_SUFFIXES))
            base_text = self.title_text[:suffix_start]
            superscript = self.title_text[suffix_start:]
            if not superscript:
                painter.setFont(f)
                draw_text_with_glow(painter, text_rect, Qt.AlignmentFlag.AlignCenter,
                                    self.title_text, self.text_color, self)
            else:
                superscript_font = QFont(f)
                superscript_font.setPointSizeF(max(8.0, f.pointSizeF() * 0.48))
                base_metrics = QFontMetricsF(f)
                super_metrics = QFontMetricsF(superscript_font)
                total_w = base_metrics.horizontalAdvance(base_text) + super_metrics.horizontalAdvance(superscript)
                start_x = text_rect.center().x() - total_w / 2.0
                baseline = text_rect.center().y() + (base_metrics.ascent() - base_metrics.descent()) / 2.0
                painter.setFont(f)
                draw_point_text_with_glow(painter, QPointF(start_x, baseline), base_text,
                                          self.text_color, self)
                painter.setFont(superscript_font)
                super_baseline = baseline - base_metrics.ascent() * 0.48
                draw_point_text_with_glow(
                    painter,
                    QPointF(start_x + base_metrics.horizontalAdvance(base_text), super_baseline),
                    superscript, self.text_color, self,
                )

        painter.restore()



# ==============================================================================
# STANDALONE IMPORTED LOGO ITEM
# ==============================================================================

class StandaloneLogoItem(DraggableStudioItem):
    """Independent imported logo: centered on import, freely movable/resizable."""
    def __init__(self, file_path, center_x=CENTER_X, center_y=CENTER_Y, app=None):
        pix = TournamentLogoItem._load_and_trim_logo(file_path)
        if pix is None or pix.isNull():
            raise ValueError(f"Could not load logo: {file_path}")
        ratio = pix.width() / max(1.0, pix.height())
        width = min(420.0, max(180.0, pix.width() * 0.55))
        height = width / max(0.05, ratio)
        if height > 300:
            height = 300.0
            width = height * ratio
        super().__init__(center_x, center_y, width, height, app=app, role="standalone_logo")
        self._source_path = os.path.abspath(file_path)
        self._pixmap = pix
        self._aspect_locked = True
        self._aspect_ratio = ratio
        self.logo_glow_enabled = False
        self.logo_glow_color = QColor("#00e575")
        self.logo_glow_intensity = 58
        self.logo_glow_opacity = 60
        self._logo_glow_cache = None
        self._logo_glow_cache_key = None
        self._logo_glow_pad = 0
        self.setZValue(45)

    def source_path(self):
        return self._source_path

    def _invalidate_logo_glow_cache(self):
        self._logo_glow_cache = None
        self._logo_glow_cache_key = None
        self._logo_glow_pad = 0

    def _glow_padding(self):
        if not self.logo_glow_enabled or self.logo_glow_opacity <= 0 or self.logo_glow_intensity <= 0:
            return 0.0
        return 14.0 + self.logo_glow_intensity * 0.52

    def boundingRect(self):
        pad = self._glow_padding()
        hw, hh = self._w / 2.0, self._h / 2.0
        return QRectF(-hw - pad, -hh - pad, self._w + 2 * pad, self._h + 2 * pad)

    def _tinted(self):
        key = (int(self._pixmap.cacheKey()), int(self.logo_glow_color.rgba()))
        if self._logo_glow_cache is not None and self._logo_glow_cache_key == key:
            return self._logo_glow_cache
        img = self._pixmap.toImage().convertToFormat(QImage.Format.Format_ARGB32)
        tinted = QImage(img.size(), QImage.Format.Format_ARGB32)
        tinted.fill(Qt.GlobalColor.transparent)
        p = QPainter(tinted)
        p.drawImage(0, 0, img)
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceIn)
        c = QColor(self.logo_glow_color); c.setAlpha(255)
        p.fillRect(tinted.rect(), c)
        p.end()
        self._logo_glow_cache = QPixmap.fromImage(tinted)
        self._logo_glow_cache_key = key
        return self._logo_glow_cache

    def paint(self, painter, option, widget=None):
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        hw, hh = self._w / 2.0, self._h / 2.0
        draw_rect = QRectF(-hw, -hh, self._w, self._h)
        if self.logo_glow_enabled and self.logo_glow_opacity > 0 and self.logo_glow_intensity > 0:
            w = max(2, int(round(draw_rect.width())))
            h = max(2, int(round(draw_rect.height())))
            key = (int(self._pixmap.cacheKey()), w, h, int(self.logo_glow_color.rgba()),
                   int(self.logo_glow_intensity), int(self.logo_glow_opacity))
            if self._logo_glow_cache is None or self._logo_glow_cache.isNull() or self._logo_glow_cache_key != key:
                scaled = self._pixmap.scaled(w, h, Qt.AspectRatioMode.IgnoreAspectRatio,
                                             Qt.TransformationMode.SmoothTransformation)
                blur = 4.0 + (self.logo_glow_intensity / 100.0) * 20.0
                opacity = (self.logo_glow_opacity / 100.0) * 0.96
                glow, pad = _build_single_blur_glow(scaled, self.logo_glow_color, blur, opacity)
                self._logo_glow_cache = glow
                self._logo_glow_cache_key = key
                self._logo_glow_pad = pad
            if self._logo_glow_cache is not None and not self._logo_glow_cache.isNull():
                painter.setOpacity(1.0)
                painter.drawPixmap(int(round(draw_rect.left() - self._logo_glow_pad)),
                                   int(round(draw_rect.top() - self._logo_glow_pad)), self._logo_glow_cache)
        painter.drawPixmap(draw_rect.toRect(), self._pixmap)
        painter.restore()

# ==============================================================================
# GENERIC EDITABLE TEXT ITEM (CANVA-STYLE)
# ==============================================================================

class EditableTextItem(QGraphicsTextItem):
    """
    Free text line with Canva-style alignment, letter spacing, font size,
    and bounding box handles.
    """
    def __init__(self, text, font, color, center_x, center_y, app=None, role="custom_text"):
        super().__init__(text)
        self.setFlags(
            QGraphicsTextItem.GraphicsItemFlag.ItemIsMovable
            | QGraphicsTextItem.GraphicsItemFlag.ItemIsSelectable
            | QGraphicsTextItem.GraphicsItemFlag.ItemSendsGeometryChanges
        )
        self.setFont(font)
        self.setDefaultTextColor(color)
        self._center = QPointF(center_x, center_y)
        self.app = app
        self.role = role
        init_text_glow(self)
        self.align = "center"
        self.letter_spacing_px = 0
        self._box_w = None
        self._box_h = None
        self._suppress_move = False
        self._apply_alignment()
        self._recenter()

    def refresh_text_glow(self):
        self.setGraphicsEffect(None)
        self.update()

    def paint(self, painter, option, widget=None):
        painter.save()
        draw_box_glow(painter, self.boundingRect().adjusted(3, 3, -3, -3), self, 8)
        painter.restore()
        super().paint(painter, option, widget)

    def boundingRect(self):
        natural = super().boundingRect()
        if self._box_w is None or self._box_h is None:
            return natural
        return QRectF(0, 0, self._box_w, self._box_h)

    def center(self):
        return (self._center.x(), self._center.y())

    def set_center(self, x, y):
        self._center = QPointF(x, y)
        self._recenter()

    def size(self):
        rect = self.boundingRect()
        return (rect.width(), rect.height())

    def half_size(self):
        rect = self.boundingRect()
        return (rect.width() / 2.0, rect.height() / 2.0)

    def _recenter(self):
        rect = self.boundingRect()
        self._suppress_move = True
        self.setPos(self._center.x() - rect.width() / 2.0, self._center.y() - rect.height() / 2.0)
        self._suppress_move = False
        if self.app:
            self.app.reposition_handles()

    def set_text(self, text):
        self.setPlainText(text)
        self._apply_alignment()
        self._recenter()

    def set_style(self, font=None, color=None):
        if font is not None:
            self.setFont(font)
            self._apply_alignment()
        if color is not None:
            self.setDefaultTextColor(color)
        self._recenter()

    def set_letter_spacing(self, px):
        self.letter_spacing_px = px
        f = self.font()
        f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, px)
        self.setFont(f)
        self._apply_alignment()
        self._recenter()

    def _apply_alignment(self):
        doc = self.document()
        qt_align = {
            "left": Qt.AlignmentFlag.AlignLeft,
            "center": Qt.AlignmentFlag.AlignHCenter,
            "right": Qt.AlignmentFlag.AlignRight,
        }.get(self.align, Qt.AlignmentFlag.AlignHCenter)
        opt = QTextOption()
        opt.setAlignment(qt_align)
        doc.setDefaultTextOption(opt)

    def mousePressEvent(self, event):
        if self.app:
            self.app.push_undo_snapshot()
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        super().mouseReleaseEvent(event)
        if self.app:
            self.app.clear_guides()
            self.app.commit_history_state()

    def itemChange(self, change, value):
        if (
            change == QGraphicsTextItem.GraphicsItemChange.ItemPositionChange
            and self.app and not self._suppress_move
            and hasattr(self.app, "snap_enabled_checkbox")
        ):
            hw, hh = self.half_size()
            proposed_center = QPointF(value.x() + hw, value.y() + hh)
            snapped = self.app.snap_center(self, proposed_center, hw, hh)
            return QPointF(snapped.x() - hw, snapped.y() - hh)

        if (
            change == QGraphicsTextItem.GraphicsItemChange.ItemPositionHasChanged
            and not self._suppress_move
        ):
            rect = self.boundingRect()
            self._center = QPointF(self.x() + rect.width() / 2.0, self.y() + rect.height() / 2.0)
            if self.app:
                self.app.reposition_handles()

        return super().itemChange(change, value)

    def shadow_settings(self):
        return copy.deepcopy(getattr(self, "_shadow", DEFAULT_SHADOW))

    def set_shadow_settings(self, settings):
        self._shadow = {**DEFAULT_SHADOW, **(settings or {})}



