    # --------------------------------------------------------------------------
    # MODERN REDESIGNED UI & STUDIO CONTROLS
    # --------------------------------------------------------------------------
    def _build_sidebar(self):
        """Build a compact, task-focused editor sidebar.

        v4.8 keeps every existing feature, but reorganizes the controls into
        four simple work areas inspired by the cleaner reference UI:
        Players, Match, Design and Save. Player 1/2 and Left/Right flag options
        use nested tabs so the panel stays short and easy to scan.
        """
        dock = QDockWidget("Properties", self)
        dock.setAllowedAreas(Qt.DockWidgetArea.RightDockWidgetArea | Qt.DockWidgetArea.LeftDockWidgetArea)
        dock.setFeatures(QDockWidget.DockWidgetFeature.NoDockWidgetFeatures)
        dock.setMinimumWidth(400)

        panel = QWidget()
        layout = QVBoxLayout(panel)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        # Compact global action row — always visible.
        action_row = QHBoxLayout()
        self.btn_undo = QPushButton("← Undo")
        self.btn_undo.setToolTip("Undo last change (Ctrl+Z)")
        self.btn_undo.clicked.connect(self.undo)
        self.btn_redo = QPushButton("Redo →")
        self.btn_redo.setToolTip("Redo last undone change (Ctrl+Y)")
        self.btn_redo.clicked.connect(self.redo)
        btn_delete = QPushButton("Delete")
        btn_delete.setObjectName("dangerButton")
        btn_delete.setToolTip("Delete selected canvas element")
        btn_delete.clicked.connect(self._delete_selected_element)
        action_row.addWidget(self.btn_undo)
        action_row.addWidget(self.btn_redo)
        action_row.addWidget(btn_delete)
        layout.addLayout(action_row)

        # Main workflow tabs. Each tab scrolls independently, like the cleaner
        # reference editor, so the whole sidebar never becomes one giant page.
        # Keep persistent references so selecting an object on the canvas can
        # automatically open the control panel that belongs to that object.
        tabs = QTabWidget()
        self.main_control_tabs = tabs
        self._control_tab_indexes = {}
        self._control_tab_scrolls = {}

        def make_tab(title):
            content = QWidget()
            content_layout = QVBoxLayout(content)
            content_layout.setContentsMargins(8, 10, 8, 10)
            content_layout.setSpacing(8)
            page_scroll = QScrollArea()
            page_scroll.setWidgetResizable(True)
            page_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
            page_scroll.setFrameShape(QFrame.Shape.NoFrame)
            page_scroll.setWidget(content)
            index = tabs.addTab(page_scroll, title)
            self._control_tab_indexes[title.lower()] = index
            self._control_tab_scrolls[title.lower()] = page_scroll
            return content_layout

        lay_players = make_tab("Players")
        lay_match = make_tab("Match")
        lay_design = make_tab("Design")
        lay_save = make_tab("Save")
        layout.addWidget(tabs, 1)

        # ==================================================================
        # PLAYERS — Player 1 / Player 2 are separated into sub-tabs.
        # ==================================================================
        player_tabs = QTabWidget()
        self.player_control_tabs = player_tabs
        p1_page, p2_page = QWidget(), QWidget()
        p1_lay, p2_lay = QVBoxLayout(p1_page), QVBoxLayout(p2_page)
        for pl in (p1_lay, p2_lay):
            pl.setContentsMargins(6, 8, 6, 8)
            pl.setSpacing(8)
        player_tabs.addTab(p1_page, "Player 1")
        player_tabs.addTab(p2_page, "Player 2")
        lay_players.addWidget(player_tabs)

        def build_player_panel(target_layout, player, nameplate, side):
            is_left = side == "left"

            basic = QGroupBox("Player")
            basic_l = QVBoxLayout()
            photo_row = QHBoxLayout()
            btn_replace = QPushButton("Replace Image…")
            btn_replace.clicked.connect(lambda: self._load_player_photo(player))
            btn_remove = QPushButton("Remove")
            btn_remove.clicked.connect(lambda: self._clear_player_photo(player))
            btn_flip = QPushButton("Mirror")
            btn_flip.clicked.connect(lambda: self._toggle_flip(player))
            photo_row.addWidget(btn_replace)
            photo_row.addWidget(btn_remove)
            photo_row.addWidget(btn_flip)
            basic_l.addLayout(photo_row)

            name_row = QHBoxLayout()
            name_row.addWidget(QLabel("Name"))
            name_edit = QLineEdit(nameplate.text)
            name_edit.textChanged.connect(lambda t, np=nameplate: (np.set_name(t), self.push_undo_snapshot()))
            name_row.addWidget(name_edit, 1)
            basic_l.addLayout(name_row)

            split_chk = QCheckBox("FIRST regular + LAST bold italic")
            split_chk.setChecked(nameplate.reference_split_style)
            split_chk.toggled.connect(lambda c, np=nameplate: self._set_reference_name_style(np, c))
            line_chk = QCheckBox("Accent line below name")
            line_chk.setChecked(nameplate.accent_line_enabled)
            line_chk.toggled.connect(lambda c, np=nameplate: self._set_nameplate_accent_line(np, c))
            basic_l.addWidget(split_chk)
            basic_l.addWidget(line_chk)

            slant_row = QHBoxLayout()
            slant_row.addWidget(QLabel("Plate"))
            plate_slant = QDoubleSpinBox(); plate_slant.setRange(-45.0, 45.0); plate_slant.setValue(15.0)
            plate_slant.valueChanged.connect(lambda v, np=nameplate: self._set_nameplate_slant(np, v))
            slant_row.addWidget(plate_slant)
            slant_row.addWidget(QLabel("Text"))
            text_slant = QDoubleSpinBox(); text_slant.setRange(-45.0, 45.0); text_slant.setValue(0.0)
            text_slant.valueChanged.connect(lambda v, np=nameplate: self._set_nameplate_text_slant(np, v))
            slant_row.addWidget(text_slant)
            basic_l.addLayout(slant_row)
            basic.setLayout(basic_l)
            target_layout.addWidget(basic)

            effects = QGroupBox("Effects")
            effects_l = QVBoxLayout()
            glow_row = QHBoxLayout()
            glow_chk = QCheckBox("Glow")
            glow_chk.setChecked(player.glow_enabled)
            glow_chk.toggled.connect(lambda c, p=player: self._set_player_glow_enabled(p, c))
            glow_btn = QPushButton("Color…")
            glow_btn.setStyleSheet(f"background:{player.glow_color.name()}; color:#001b0e; font-weight:700;")
            glow_btn.clicked.connect(lambda _=False, p=player, b=glow_btn: self._pick_player_glow_color(p, b))
            glow_row.addWidget(glow_chk)
            glow_row.addWidget(glow_btn)
            effects_l.addLayout(glow_row)

            glow_power = QHBoxLayout()
            glow_power.addWidget(QLabel("Intensity"))
            glow_int = QSpinBox(); glow_int.setRange(0, 100); glow_int.setValue(player.glow_intensity); glow_int.setSuffix(" %")
            glow_int.valueChanged.connect(lambda v, p=player: self._set_player_glow_intensity(p, v))
            glow_power.addWidget(glow_int)
            glow_power.addWidget(QLabel("Opacity"))
            glow_op = QSpinBox(); glow_op.setRange(0, 100); glow_op.setValue(player.glow_opacity); glow_op.setSuffix(" %")
            glow_op.valueChanged.connect(lambda v, p=player: self._set_player_glow_opacity(p, v))
            glow_power.addWidget(glow_op)
            effects_l.addLayout(glow_power)

            # Shadow options are shown anywhere a glow exists, matching the
            # requested direction menu (Left/Right/Top/Bottom + diagonals).
            shadow = player.shadow_settings()
            shadow_row = QHBoxLayout()
            shadow_chk = QCheckBox("Shadow"); shadow_chk.setChecked(bool(shadow.get("enabled")))
            shadow_chk.toggled.connect(lambda c, p=player: self._set_item_shadow_enabled(p, c))
            shadow_dir = QComboBox(); shadow_dir.addItems(list(SHADOW_DIRECTIONS.keys())); shadow_dir.setCurrentText(shadow.get("direction", "Bottom-Right"))
            shadow_dir.currentTextChanged.connect(lambda d, p=player: self._set_item_shadow_direction(p, d))
            shadow_color = QPushButton("Shadow Color…")
            shadow_color.clicked.connect(lambda _=False, p=player, b=shadow_color: self._pick_item_shadow_color(p, b))
            shadow_row.addWidget(shadow_chk); shadow_row.addWidget(shadow_dir, 1); shadow_row.addWidget(shadow_color)
            effects_l.addLayout(shadow_row)
            shadow_nums = QHBoxLayout(); shadow_nums.addWidget(QLabel("Distance"))
            sh_dist = QSpinBox(); sh_dist.setRange(0, 150); sh_dist.setValue(int(shadow.get("distance", 22))); sh_dist.valueChanged.connect(lambda v, p=player: self._set_item_shadow_distance(p, v)); shadow_nums.addWidget(sh_dist)
            shadow_nums.addWidget(QLabel("Blur")); sh_blur = QSpinBox(); sh_blur.setRange(0, 150); sh_blur.setValue(int(shadow.get("blur", 35))); sh_blur.valueChanged.connect(lambda v, p=player: self._set_item_shadow_blur(p, v)); shadow_nums.addWidget(sh_blur)
            shadow_nums.addWidget(QLabel("Opacity")); sh_op = QSpinBox(); sh_op.setRange(0, 100); sh_op.setValue(int(shadow.get("opacity", 60))); sh_op.valueChanged.connect(lambda v, p=player: self._set_item_shadow_opacity(p, v)); shadow_nums.addWidget(sh_op)
            effects_l.addLayout(shadow_nums)

            under_row = QHBoxLayout()
            under_chk = QCheckBox("Underline")
            under_chk.setChecked(player.underline_enabled)
            under_chk.toggled.connect(lambda c, p=player: self._set_player_underline_enabled(p, c))
            under_color = QPushButton("Line Color…")
            under_color.clicked.connect(lambda _=False, p=player: self._pick_player_underline_color(p))
            under_row.addWidget(under_chk)
            under_row.addWidget(under_color)
            effects_l.addLayout(under_row)

            under_size = QHBoxLayout()
            under_size.addWidget(QLabel("Thickness"))
            und_thk = QSpinBox(); und_thk.setRange(1, 30); und_thk.setValue(int(player.underline_thickness))
            und_thk.valueChanged.connect(lambda v, p=player: self._set_player_underline_thickness(p, v))
            under_size.addWidget(und_thk)
            under_size.addWidget(QLabel("Width"))
            und_w = QSpinBox(); und_w.setRange(50, 900); und_w.setValue(int(player.underline_width))
            und_w.valueChanged.connect(lambda v, p=player: self._set_player_underline_width(p, v))
            under_size.addWidget(und_w)
            effects_l.addLayout(under_size)
            effects.setLayout(effects_l)
            target_layout.addWidget(effects)
            target_layout.addStretch()

            if is_left:
                self.input_name_l = name_edit
                self.chk_split_name_l = split_chk
                self.chk_name_line_l = line_chk
                self.spin_slant_l = plate_slant
                self.spin_text_slant_l = text_slant
                self.chk_glow_l = glow_chk
                self.btn_glow_col_l = glow_btn
                self.spin_glow_int_l = glow_int
                self.spin_glow_op_l = glow_op
                self.chk_shadow_l = shadow_chk
                self.combo_shadow_dir_l = shadow_dir
                self.spin_shadow_dist_l = sh_dist
                self.spin_shadow_blur_l = sh_blur
                self.spin_shadow_op_l = sh_op
                self.chk_und_l = under_chk
                self.spin_und_thk_l = und_thk
                self.spin_und_w_l = und_w
            else:
                self.input_name_r = name_edit
                self.chk_split_name_r = split_chk
                self.chk_name_line_r = line_chk
                self.spin_slant_r = plate_slant
                self.spin_text_slant_r = text_slant
                self.chk_glow_r = glow_chk
                self.btn_glow_col_r = glow_btn
                self.spin_glow_int_r = glow_int
                self.spin_glow_op_r = glow_op
                self.chk_shadow_r = shadow_chk
                self.combo_shadow_dir_r = shadow_dir
                self.spin_shadow_dist_r = sh_dist
                self.spin_shadow_blur_r = sh_blur
                self.spin_shadow_op_r = sh_op
                self.chk_und_r = under_chk
                self.spin_und_thk_r = und_thk
                self.spin_und_w_r = und_w

        build_player_panel(p1_lay, self.player_left, self.nameplate_left, "left")
        build_player_panel(p2_lay, self.player_right, self.nameplate_right, "right")
        lay_players.addStretch()

        # ==================================================================
        # MATCH — banners, countries and compact left/right flag sub-tabs.
        # ==================================================================
        grp_badges = QGroupBox("Match Text")
        self.grp_match_text_controls = grp_badges
        l_bdg = QVBoxLayout()
        row_day = QHBoxLayout(); row_day.addWidget(QLabel("Top"))
        self.input_day_text = QLineEdit(self.banner_day.text)
        self.input_day_text.textChanged.connect(lambda t: (self.banner_day.set_banner_text(t), self.push_undo_snapshot()))
        row_day.addWidget(self.input_day_text, 1); l_bdg.addLayout(row_day)
        row_match = QHBoxLayout(); row_match.addWidget(QLabel("Bottom"))
        self.input_match_text = QLineEdit(self.banner_match.text)
        self.input_match_text.textChanged.connect(lambda t: (self.banner_match.set_banner_text(t), self.push_undo_snapshot()))
        row_match.addWidget(self.input_match_text, 1); l_bdg.addLayout(row_match)
        row_bslant = QHBoxLayout(); row_bslant.addWidget(QLabel("Slant"))
        self.spin_banner_slant = QDoubleSpinBox(); self.spin_banner_slant.setRange(-45.0, 45.0); self.spin_banner_slant.setValue(15.0)
        self.spin_banner_slant.valueChanged.connect(self._on_banner_slant_changed)
        row_bslant.addWidget(self.spin_banner_slant); row_bslant.addStretch(); l_bdg.addLayout(row_bslant)
        grp_badges.setLayout(l_bdg)
        lay_match.addWidget(grp_badges)

        grp_teams = QGroupBox("Countries & Flags")
        self.grp_country_flag_controls = grp_teams
        l_tms = QVBoxLayout()
        code_row = QHBoxLayout()
        self.input_code_l = QLineEdit(self.pill_left.country_code); self.input_code_l.setPlaceholderText("IND")
        self.input_code_l.editingFinished.connect(lambda: self._apply_country_code_input(self.input_code_l, self.pill_left))
        btn_flag_l = QPushButton("Left Flag…"); btn_flag_l.clicked.connect(lambda: self._load_custom_flag(self.pill_left))
        self.input_code_r = QLineEdit(self.pill_right.country_code); self.input_code_r.setPlaceholderText("KOR")
        self.input_code_r.editingFinished.connect(lambda: self._apply_country_code_input(self.input_code_r, self.pill_right))
        btn_flag_r = QPushButton("Right Flag…"); btn_flag_r.clicked.connect(lambda: self._load_custom_flag(self.pill_right))
        code_row.addWidget(self.input_code_l); code_row.addWidget(btn_flag_l)
        code_row.addWidget(self.input_code_r); code_row.addWidget(btn_flag_r)
        l_tms.addLayout(code_row)

        auto_row = QHBoxLayout()
        self.input_auto_country = QLineEdit(); self.input_auto_country.setPlaceholderText("Type country name")
        btn_auto_l = QPushButton("Set Left"); btn_auto_l.clicked.connect(lambda: self._auto_fetch_flag(self.input_auto_country.text(), self.pill_left, self.input_code_l))
        btn_auto_r = QPushButton("Set Right"); btn_auto_r.clicked.connect(lambda: self._auto_fetch_flag(self.input_auto_country.text(), self.pill_right, self.input_code_r))
        auto_row.addWidget(self.input_auto_country, 1); auto_row.addWidget(btn_auto_l); auto_row.addWidget(btn_auto_r)
