    # --------------------------------------------------------------------------
    # LOGO MANAGEMENT ACTIONS (REQ 2)
    # --------------------------------------------------------------------------
    def _choose_logo_files(self, title):
        paths, _ = QFileDialog.getOpenFileNames(
            self, title, "",
            "Images (*.png *.jpg *.jpeg *.webp *.svg *.bmp)"
        )
        return paths or []

    def _refresh_logo_list_ui(self):
        if not hasattr(self, "logo_list"):
            return
        current_row = self.logo_list.currentRow()
        self.logo_list.blockSignals(True)
        self.logo_list.clear()
        for i, item in enumerate(getattr(self, "extra_logo_items", []), start=1):
            self.logo_list.addItem(f"{i}. {os.path.basename(item.source_path())}")
        if self.logo_list.count() > 0:
            self.logo_list.setCurrentRow(min(max(0, current_row), self.logo_list.count() - 1))
        self.logo_list.blockSignals(False)

    def _select_logo_from_list(self, row):
        items = getattr(self, "extra_logo_items", [])
        if row < 0 or row >= len(items):
            return
        self.scene.clearSelection()
        item = items[row]
        item.setSelected(True)
        self._sync_logo_effect_controls(item)

    def _create_imported_logo_item(self, path):
        item = StandaloneLogoItem(path, CENTER_X, CENTER_Y, app=self)
        # All imports intentionally start in the exact canvas center. They are
        # independent items, so users can drag each one wherever needed.
        self.scene.addItem(item)
        self.extra_logo_items.append(item)
        return item

    def _upload_custom_logos_replace(self):
        paths = self._choose_logo_files("Import Logo(s)")
        if not paths:
            return
        self.push_undo_snapshot()
        for item in list(getattr(self, "extra_logo_items", [])):
            if item.scene() is self.scene:
                self.scene.removeItem(item)
        self.extra_logo_items = []
        loaded = 0
        last = None
        for path in paths:
            try:
                last = self._create_imported_logo_item(path)
                loaded += 1
            except Exception:
                continue
        if loaded:
            # "Replace" means imported logos replace the default mark visually.
            self.tournament_header.show_logo = False
            if hasattr(self, "chk_show_logo"):
                self.chk_show_logo.blockSignals(True); self.chk_show_logo.setChecked(False); self.chk_show_logo.blockSignals(False)
            self._refresh_logo_list_ui()
            self.logo_list.setCurrentRow(loaded - 1)
            if last is not None:
                self.scene.clearSelection(); last.setSelected(True)
            self.statusBar().showMessage(f"Imported {loaded} movable logo(s) in the canvas center.", 3500)
        else:
            QMessageBox.warning(self, "Load Error", "None of the selected logo files could be read.")

    def _upload_custom_logos_add(self):
        paths = self._choose_logo_files("Add Logo(s)")
        if not paths:
            return
        self.push_undo_snapshot()
        loaded = 0
        last = None
        for path in paths:
            try:
                last = self._create_imported_logo_item(path)
                loaded += 1
            except Exception:
                continue
        if loaded:
            self._refresh_logo_list_ui()
            self.logo_list.setCurrentRow(len(self.extra_logo_items) - 1)
            if last is not None:
                self.scene.clearSelection(); last.setSelected(True)
            self.statusBar().showMessage(f"Added {loaded} movable logo(s) in the canvas center.", 3500)
        else:
            QMessageBox.warning(self, "Load Error", "None of the selected logo files could be read.")

    def _upload_custom_logo(self):
        """Backward-compatible alias used by older UI bindings."""
        self._upload_custom_logos_replace()

    def _remove_selected_logo(self):
        if not hasattr(self, "logo_list") or self.logo_list.currentRow() < 0:
            self.statusBar().showMessage("Select an imported logo from the list first.", 2200)
            return
        row = self.logo_list.currentRow()
        if row >= len(self.extra_logo_items):
            return
        self.push_undo_snapshot()
        item = self.extra_logo_items.pop(row)
        if item.scene() is self.scene:
            self.scene.removeItem(item)
        self._refresh_logo_list_ui()
        self.statusBar().showMessage("Imported logo removed.", 2200)

    def _remove_logo(self):
        self.push_undo_snapshot()
        for item in list(getattr(self, "extra_logo_items", [])):
            if item.scene() is self.scene:
                self.scene.removeItem(item)
        self.extra_logo_items = []
        self._refresh_logo_list_ui()
        self.statusBar().showMessage("All imported logos cleared.", 2200)

    def _reset_logo(self):
        self.push_undo_snapshot()
        for item in list(getattr(self, "extra_logo_items", [])):
            if item.scene() is self.scene:
                self.scene.removeItem(item)
        self.extra_logo_items = []
        self.tournament_header.reset_to_davis_cup()
        self.chk_show_logo.blockSignals(True); self.chk_show_logo.setChecked(True); self.chk_show_logo.blockSignals(False)
        self.chk_show_title.blockSignals(True); self.chk_show_title.setChecked(False); self.chk_show_title.blockSignals(False)
        self.input_header_text.setText(self.tournament_header.title_text)
        self._refresh_logo_list_ui()
        self.scene.clearSelection(); self.tournament_header.setSelected(True)
        self.statusBar().showMessage("Restored the embedded Davis Cup default logo.", 3000)

