    def _sync_logo_effect_controls(self, item=None):
        target = item if isinstance(item, (StandaloneLogoItem, TournamentLogoItem)) else self._active_logo_target()
        if hasattr(self, "chk_logo_glow"):
            self.chk_logo_glow.blockSignals(True); self.chk_logo_glow.setChecked(target.logo_glow_enabled); self.chk_logo_glow.blockSignals(False)
        if hasattr(self, "spin_logo_glow_int"):
            self.spin_logo_glow_int.blockSignals(True); self.spin_logo_glow_int.setValue(int(target.logo_glow_intensity)); self.spin_logo_glow_int.blockSignals(False)
        if hasattr(self, "spin_logo_glow_op"):
            self.spin_logo_glow_op.blockSignals(True); self.spin_logo_glow_op.setValue(int(target.logo_glow_opacity)); self.spin_logo_glow_op.blockSignals(False)
        if hasattr(self, "btn_logo_glow_color"):
            c = target.logo_glow_color
            self.btn_logo_glow_color.setStyleSheet(f"background:{c.name()}; color:{'#000000' if c.lightness() > 145 else '#ffffff'}; font-weight:700;")
        s = target.shadow_settings()
        if hasattr(self, "chk_logo_shadow"):
            self.chk_logo_shadow.blockSignals(True); self.chk_logo_shadow.setChecked(bool(s.get("enabled"))); self.chk_logo_shadow.blockSignals(False)
        if hasattr(self, "combo_logo_shadow_dir"):
            self.combo_logo_shadow_dir.blockSignals(True); self.combo_logo_shadow_dir.setCurrentText(s.get("direction", "Bottom-Right")); self.combo_logo_shadow_dir.blockSignals(False)
        for name, key in (("spin_logo_shadow_dist", "distance"), ("spin_logo_shadow_blur", "blur"), ("spin_logo_shadow_op", "opacity")):
            if hasattr(self, name):
                w = getattr(self, name); w.blockSignals(True); w.setValue(int(s.get(key, DEFAULT_SHADOW[key]))); w.blockSignals(False)

